  "auth.aboutLink": "Game da Luminous StockHaven",
  'about.bookshopLeadIn': "Ƙaramin kasuwancin da ke gudanar da shagon littattafanmu ne ya yi shi:",
  "about.eyebrow": "Game da Luminous StockHaven",
  "about.pageTitle": "Luminous StockHaven — Game da Mu",
  "about.founderHeading": "📖 Game da Wadda ta Kafa",
  "about.founder.p1": "Sannu, ni ce Concepcion, wadda ta kafa Luminous StockHaven.",
  "about.founder.p2": "Ban fito daga babban kamfanin fasaha ba, kuma ba na zaune a ofishin kamfani. Ni ƙaramar mai shago ce, kamar kai. Ina gudanar da shaguna biyar na intanet waɗanda suka ƙware a littattafai da kayan hannu ga masu son littattafai.\nKamar yawancin masu sayarwa masu zaman kansu, na kai ga matakin karyewa yayin da nake ƙoƙarin sarrafa kaya a wurare da yawa, bin ISBN na masu wallafawa tare da SKU nawa na hannu, da kula da odar masu kaya da takardun lissafi masu wahala. Lokacin da na nemi manhajar da za ta taimake ni, na gwada zaɓuɓɓuka shida daban-daban. Kowane ya kasance ko bai cika ba sam, ko yana da rikitarwa sosai, ko na zalunci — suna karɓar ɗaruruwan dala a wata don kayan aiki na asali.",
  "about.founder.p3": "Cikin takaici da masana’antar da ke zaluntar masu ƙirƙira masu zaman kansu, na yanke shawarar gina mafita ta kaina. Na gina Luminous StockHaven saboda buƙata, don gudanar da kasuwancina da kaina cikin tsabta, inganci, da cikakken kwanciyar hankali.",
  "about.founder.p4": "Na yanke shawarar buɗe wannan dandalin ga jama’a a farashi na gaskiya da araha, domin kowane ƙaramin mai kasuwanci ya cancanci kayan aiki da ke aiki da gaske ba tare da sanya abin da yake samu cikin haɗari ba. Mu masu zaman kansu ne, muna kare al’ummarmu da ƙarfi, kuma mai sayarwa ce ta gina mu, don masu sayarwa.",
  "notice.ariaLabel": "Sanarwar alamar kasuwanci da haƙƙin mallaka",
  "notice.heading": "🛡️ An Gina don Masu Sayarwa, Ba shi da Farashi ga Mikiyoyin Kamfanoni",
  "notice.intro": "Na gina wannan manhajar saboda ina gudanar da shaguna 5 kuma na gaji da yaudarar da ake yi mini da manhajojin da ke rikitarwa na ɗaruruwan dala. An gina wannan manhajar don kare masu fasaha masu zaman kansu, masu sana’a, masu sayar da littattafai, da shagunan gida.",
  "notice.legalHeading": "SANARWAR DOKA GA ABOKAN HAMA DA MASU KOPI:",
  "notice.legalBody": "Muna lura da kasuwa sosai. Duk wani yunƙuri na cire bayanai daga dandalinmu, yin kwafin tsarin aikinmu na mallaka, ko keta dukiyarmu ta ilimi zai fuskanci matakin doka na gaggawa da ƙarfi.",
  "notice.acquisitionHeading": "GA KAMFANONIN SAYE DA DALALAI:",
  "notice.acquisitionBody": "Kada ku aiko mini imel. Kada ku aiko mini saƙo. Kada ku ba ni shawarar 'fita ta dabara'. Kuna iya bayar da dubbai, miliyoyi, biliyoyi, ko tiriliyoyi — amsar ita ce A’a. Ba za ku sayi wannan manhajar don kawai ku ƙara farashi ga abokan sayarwata ba. Kowane imel na saye da ba a nema ba za a yi masa alamar taka nan take, kuma za a toshe yankinku daga dandalinmu har abada. Ku tsira da wahala.",
  "footer.trademarkLine": "An haramta kwafi, yin kwafi, ko cire bayanai ba tare da izini ba sosai.",
