  "plans.backToWelcome": "Koma zuwa barka da zuwa",
  "plans.eyebrow": "Tsare-tsare da fasaloli",
  "plans.title": "Kwatanta tsare-tsaren StockHaven",
  "plans.intro": "Asusu ɗaya, duk tsarin da ka zaɓa — Business yana rufe kasuwanci har guda biyar. Farashin na wata ne a dalar Amurka, kuma sabbin abokan ciniki masu cancanta na yanar gizo za su iya samun gwaji ɗaya na kwana bakwai a tsakanin Essentials da Business. Haɓaka biyan Essentials da ke akwai zuwa Business ba ya sake fara gwaji ko ƙirƙirar wani gwaji kyauta. Farashin tsarin yanar gizo kafin harajin da ya dace ne, idan akwai. Za a nuna maka cajinka na ainihi kafin ka ba da izinin biyan kuɗi.",
  "plans.availableAtLaunch": "Akwai a lokacin ƙaddamarwa",
