  "plans.included": "Ya haɗa da",
  "plans.notIncluded": "Ba ya haɗa da",
  "plans.mobileIncludedNote": "Tsare-tsaren yanar gizo biyu sun haɗa da abokin waya, don haka mai biyan yanar gizo ba ya biyan kuɗin waya na wata daban.",
  "plans.priceNote": "Essentials $14.99/wata ne tare da harajin da ya dace, idan akwai. Business $29.99/wata ne tare da harajin da ya dace, idan akwai. Duk harajin da ake buƙata ana ƙayyade shi yayin biyan mai bayarwa kuma dole ne ya bayyana a jimillar ƙarshe kafin biya. Wannan shafin kwatance ba ƙiyasin haraji ba ne ko izinin biya.",
  "plans.mobilePriceNote": "Tsarin waya kaɗai $4.99/wata ne a farashinsa na asali na Amurka. App Store ko Google Play suna nuna ainihin farashin biyan kuɗi na yankin da duk harajin da ya dace kafin saya. Izinin samfurinsa, shafi da ma'aikata ana saita su a ƙaddamarwa, daban da matakan yanar gizo.",
  "plans.planChangeNote": "Canjin tsarin yanar gizo dole ne mai bayar da biyan kuɗi ya tabbatar da shi. Za a bayyana sabon farashi, ranar fara aiki da duk wani ragi kafin a ba da izinin canjin. Haɓakawa bai kamata ya ƙirƙiri biyan kuɗi na biyu ba.",
  "plans.providerNote": "Farashi, caji da gwaje-gwaje mai bayarwa da ka yi biyan kuɗi ta cikinsa ne ke kula da su — App Store, Google Play, yanar gizo ko Shopify — ba wannan shafi ba.",
