  "upgrade.title": "Zaɓi abin da ya dace da shagonka",
  "upgrade.pendingCheckoutIntro": "Wannan sabon wurin aiki yana iyakance ga Essentials har sai ka zaɓi biyan kuɗi. Sabbin abokan ciniki masu cancanta za su iya samun gwaji ɗaya na kwana {days} a kowane asusu.",
  "upgrade.intro": "Sabbin abokan ciniki masu cancanta za su iya samun gwaji ɗaya na kwana {days} a kowane asusu, ba gwaji ɗaya a kowane tsari ba. Canzawa daga Essentials zuwa Business ba ya fara wani gwaji kyauta. Kana kan",
