  "upgrade.introTrial": " (gwaji).",
  "upgrade.introPeriod": ".",
  "upgrade.pastDueTitle": "Biyan ya wuce lokaci",
  "upgrade.pastDueBody": "Biyan kuɗin ku na ƙarshe bai yi nasara ba, don haka wannan rajista ta wuce lokaci. Kuna riƙe cikakken amfani na kwanaki 14 daga biyan da ya gaza yayin da kuke gyara shi. Idan ba a gyara ba, za a soke rajistar, wurin aiki zai zama kallo kawai na kwanaki 15, sannan za a goge asusun da duk bayanansa. Biya a kowane lokaci kafin gogewa yana dawo da komai. Sabunta hanyar biyan kuɗin ku a ƙasa. Idan kuna buƙatar taimako, aika imel zuwa",
  "upgrade.updatePaymentMethod": "Sabunta hanyar biya",
