  "upgrade.previewDowngradeNote": "Saukawa tana aiki a ƙarshen lokacin biyanka. Bayanan fasalolin da ka rasa ana riƙe su amma ba sa shiga — ba a taɓa share su a matsayin sakamakon saukawa ba.",
