  "billing.cancel.appStoreNote": "Idan ka taɓa yin biyan kuɗi ta Google Play ko Apple App Store, za ka iya buƙatar soke shi ta saitunan biyan kuɗi na wannan shagon. Wannan taga ba za ta iya dakatar da biyan shagon manhaja ba. Cire manhajar ko share asusun StockHaven ba ya soke biyan kuɗi na shagon.",
