  "settings.deletion.checkError": "Ba a iya duba buƙatun da ke akwai yanzu ba. Har yanzu za ka iya gwada aika buƙata.",
  "settings.deletion.confirmError": "Ba mu iya tabbatar da buƙatar sharewarka ba. Da fatan za a sake gwadawa.",
  "settings.deletion.receivedDesc": "Ba a share asusunka da bayananka ba.",
  "settings.deletion.receivedTitle": "An karɓi buƙatar share asusu",
  "settings.deletion.submitError": "Ba a iya aika buƙatarka ba. Da fatan za a sake gwadawa.",
  "settings.details.address": "Adireshi",
  'settings.details.taxRate': 'Kudin harajina',
  'settings.details.taxRateHint': 'Saita shi sau ɗaya. Kowane sabon odar sayarwa yana cike harajinsa daga wannan kudi — har yanzu za ka iya canza harajin kowane oda guda.',
  "settings.details.taxMode": "Yadda oda ke samun harajinsu",
  "settings.details.taxModeFixed": "Kudina na tsaye",
  "settings.details.taxModeAutomatic": "Kai tsaye — bisa jihar abokin ciniki",
  "settings.details.taxModeHint": "Yanayin tsaye yana amfani da kudin ka a kowace sabuwar oda. Yanayin kai tsaye yana cika harajin sabuwar oda da kudin asali na jihar abokin ciniki da zarar jihar tana kan odar, kuma yana sake cikawa idan jihar ta canza. Waɗannan kudaden asali na jiha ne — harajin gida na iya ƙara ƙari. Oda ba tare da jiha ba, ko daga wajen Amurka, tana amfani da kudin ka na tsaye a sama.",
  'settings.details.gs1Prefix': "Gabatarwar kamfanin GS1",
  'settings.details.gs1PrefixHint': "Sai idan kana da lasisin gabatarwa daga GS1. Saita sau ɗaya kuma mai ƙirƙirar lamba a fom ɗin samfur zai iya ƙirƙirar lambobin sayarwa na UPC da EAN na gaske daga lambobinka — kowane sau ɗaya kawai ake amfani da shi kuma ba a sake amfani da shi har abada. Bar shi fanko idan ba ka da shi; manhajar ba ta ƙirƙirar gabatarwa har abada.",
  'settings.details.gs1LearnMore': "Sabon zuwa ga GS1? Idan kana zaune a ƙasarka, yi amfani da hanyar haɗin ta don ƙarin sani; idan kana zaune a Amurka, yi amfani da hanyar haɗin GS1 US.",
