  "settings.pastDue.body": "Biyan kuɗin ku na ƙarshe bai yi nasara ba. Kuna riƙe cikakken amfani na kwanaki 14 daga biyan da ya gaza yayin da kuke gyara shi. Idan ba a gyara ba, za a soke rajistar, wurin aiki zai zama kallo kawai na kwanaki 15, sannan za a goge asusun da duk bayanansa. Biya a kowane lokaci kafin gogewa yana dawo da komai. Idan ba ku da tabbas kan abin da za ku yi, tuntuɓi tallafi a theluminousbookshop@outlook.com.",
