  "settings.security.title": "Tsaro da maɓallan ajiya",
  "settings.security.description": "Saita maɓallan ajiyarka KAFIN ka buƙace su: idan ka taɓa rasa damar shiga imel ɗin asusunka, su ne yadda za ka dawo da shagonka.",
  "settings.security.genericError": "Wani abu ya yi kuskure. Don Allah sake gwadawa.",
