  "settings.security.backupCodesDesc": "Maɓallan ajiya na amfani ɗaya. Buga su ko rubuta su ka riƙe su a wuri mai aminci — kowannensu zai iya mayar da kai sau ɗaya idan ka rasa imel ɗinka.",
  "settings.security.codesRemaining": "Lambobin ajiya da ba a yi amfani da su ba da suka rage: {count}",
