  "settings.security.codesOnceWarning": "Ana nuna waɗannan lambobi sau ɗaya kacal — muna riƙe kwafin da aka rurrushe kaɗai, don haka ko mu ma ba za mu iya sake nuna su ba. Samar da sabon saiti yana soke kowace tsohuwar lamba.",
  "settings.security.printCodes": "Buga waɗannan lambobi",
