  "settings.security.backupEmailDesc": "Adireshin imel na biyu da kake sarrafawa. Idan imel ɗinka na asali ya taɓa zama ba a isa gare shi ba, ana iya aika lambar maidowa a nan maimakon haka.",
  "settings.security.backupEmailLabel": "Adireshin imel ɗin ajiya",
