  "pos.title": "Haɗin til",
  "pos.webhookPending": "Ba a kunna webhooks na tallace-tallace tukuna a ɓangarenmu ba — ana ajiye haɗi, kuma tallace-tallace suna fara zuwa a lokacin da aka kunna su.",
  "training.lessons.owner-pos-connect-shopify.step1": "Haɗin til ɓangare ne na tsarin Business. Tallace-tallacen Shopify POS oda na Shopify ne, don haka haɗin ga kowane shago ne: a Shopify, ƙirƙiri manhaja ta musamman don shagonka ka kwafi token ɗin shigarta. A shafin Haɗin til, liƙa yankin shagonka (kamar your-store.myshopify.com) da token ɗin.",
  "training.lessons.owner-pos-connect-shopify.step2": "Ana ajiye token ɗin a sabar kaɗai — ba a taɓa sake nuna shi ba, ko gare ka ma. Idan ka taɓa liƙa sabo, yana maye gurbin tsohon kawai.",
  "training.lessons.owner-pos-connect-shopify.step3": "Zaɓi wane wurinka ne tallace-tallacen wannan shago ke fitowa daga gare shi, idan kana da fiye da ɗaya. Sannan kowace oda — a til na Shopify ko a yanar gizo — tana fitar da abubuwanta daga kaya a nan da kanta.",
  "training.lessons.owner-pos-connect-shopify.step4": "Shago ɗaya yana haɗawa zuwa wurin aiki ɗaya a nan. Idan an riga an haɗa yanki a wani wuri, manhajar tana faɗi haka a fili maimakon raba shi.",
  "training.lessons.owner-pos-connect-shopify.title": "Haɗa Shopify POS",
  "training.lessons.owner-pos-connect-square.step1": "Haɗin til ɓangare ne na tsarin Business. Buɗe Haɗin til (a menu na Tallace-tallace) ka danna Haɗa a katin Square. Za ka sauka a shafin Square kanta don amince da haɗin — manhajar ba ta taɓa ganin kalmar sirrinka ta Square ba.",
  "training.lessons.owner-pos-connect-square.step2": "Komawa cikin manhajar, katin yana nuna An haɗa. Idan shagonka yana da wurare fiye da ɗaya, zaɓi wane ne tallace-tallacen wannan til ke fitowa daga gare shi; in ba haka ba tallace-tallace suna fitowa daga wurinka na farko.",
  "training.lessons.owner-pos-connect-square.step3": "Daga lokacin, kowace sayarwar Square tana fitar da abubuwan daga kaya a nan da kanta. Sayar da abu ɗaya a til ka kalli jerin Tallace-tallace na baya-bayan nan a shafi ɗaya: sayarwar tana sauka cikin lokuta, an yi mata alamar an ƙidaya.",
  "training.lessons.owner-pos-connect-square.step4": "Sayarwa ba za ta taɓa ƙidayawa sau biyu ba — idan Square ta sake aika sayarwa ɗaya, manhajar tana gane ta kuma ba ta canza komai. Cire haɗi yana kan kati ɗaya, kuma yana dakatar da daidaitawar nan take.",
  "training.lessons.owner-pos-connect-square.title": "Haɗa Square: tallace-tallacen da ke motsa kayanka gare ka",
  "training.lessons.owner-pos-csv.step1": "Duk til da zai iya fitar da fayil ɗin tallace-tallace har yanzu zai iya ciyar da kayanka. Fitar da tallace-tallacen ranar a matsayin CSV tare da waɗannan ginshiƙai: sale_id, sold_at, sku_or_barcode, quantity — item_name da location suna taimako, amma na zaɓi ne.",
  "training.lessons.owner-pos-csv.step2": "Loda fayil ɗin a shafin Haɗin til. Ana rubuta kowace sale_id sau ɗaya: sake loda fayil ɗaya gobe ba ya canza komai, yana bayar da rahoton kwafi kaɗai.",
  "training.lessons.owner-pos-csv.step3": "Layukan da manhajar ba za ta iya amfani da su ba ba a taɓa tsallake su a shiru ba — layi ba tare da sale_id ba, ko yawan da ba lamba ba, ana jera shi baya gare ka tare da lambar layinsa da dalili.",
  "training.lessons.owner-pos-csv.step4": "Ana daidaita abubuwa ta SKU ko barcode, daidai kamar til mai rai. Duk abin da bai dace ba yana jira a allon daidaitawa, kamar kowace sayarwa.",
  "training.lessons.owner-pos-csv.title": "Babu API na til? CSV na ƙarshen yini",
  "training.lessons.owner-pos-mapping.step1": "Abu na til yana dacewa da samfuranka ta SKU ko barcode. Lokacin da sayarwa ta zo da abu da manhajar ba ta taɓa gani ba, wannan abu ana RIƘE shi — babu kaya da ke motsawa, kuma sayarwar tana jira a shafin Haɗin til ƙarƙashin Abubuwan da ke jiran daidaitawa.",
  "training.lessons.owner-pos-mapping.step2": "Zaɓi wane samfuranka ne wannan abu da gaske, ka ajiye. Ana tuna wannan daidaitawa har abada: kowace sayarwa ta gaba na wannan abu tana ƙidayawa da kanta.",
  "training.lessons.owner-pos-mapping.step3": "Bayan ajiyewa, danna Aiwatar ga tallace-tallacen da aka riƙe don ƙidaya tallace-tallacen da suke jira — suna rubuta motsinsu na kaya a lokacin, tare da nufin sayarwar kanta.",
  "training.lessons.owner-pos-mapping.step4": "Idan sayarwar da aka riƙe ta nemi fiye da abin da ke shelf, tana ci gaba da alamar kaya bai isa ba maimakon kai ƙidayar ƙasa da sifili. Sake cika kaya, sannan aiwatar kuma daga allo ɗaya.",
  "training.lessons.owner-pos-mapping.title": "Lokacin da abu na til bai dace ba: allon daidaitawa",
  "training.lessons.owner-pos-sales-list.step1": "Jerin Tallace-tallace na baya-bayan nan a shafin Haɗin til yana nuna kowace sayarwa da til ɗinka suka aika: wane til, lambar sayarwa, yaushe, jimillar kamar yadda til ya bayar da rahoto, da abin da ya faru ga kowane abu.",
  "training.lessons.owner-pos-sales-list.step2": "An ƙidaya yana nufin kayan ya motsa. An ƙidaya wani ɓangare yana nufin wasu abubuwa sun ƙidaya wasu kuma suna jira ko sun yi ƙasa — buɗe sayarwar don ganin waɗanne, a cikin kalmomi masu sauƙi.",
  "training.lessons.owner-pos-sales-list.step3": "An riƙe yana nufin babu abin da ke cikin wannan sayarwa da ya ƙidaya tukuna: abu yana buƙatar daidaitawa (duba darasin daidaitawa), shelf bai riƙe isa ba, ko sayarwar ta iso yayin da shagon ba ya kan tsarin Business. Duk ukun ana gyara su daga shafi ɗaya — sayarwar da aka riƙe don tsarin tana ƙidayawa daga nan da zarar shagon ya dawo kan Business — kuma babu abin da ke taɓa ɓacewa a shiru.",
  "training.lessons.owner-pos-sales-list.step4": "Kowace sayarwa da aka ƙidaya tana rubuta shigarwar An sayar ta yau da kullum a tarihin kayanka tare da nuni da ke suna til da sayarwar — don haka shafin Motsi naka da til ɗinka koyaushe suna ba da labari ɗaya.",
  "training.lessons.owner-pos-sales-list.title": "Karanta tallace-tallacen til ɗinka",
  "training.lessons.staff-pos-till-sales.step1": "Idan shagonka yana kan tsarin Business kuma ya haɗa til ɗinsa (Square ko Shopify POS), kowace sayarwa a rajista tana fitar da abin daga kaya a nan da kanta — babu fitar da dubawa, babu rubuta shi daga baya.",
  "training.lessons.staff-pos-till-sales.step2": "Za ka iya kallon shi yana faruwa a shafin Haɗin til: kowace sayarwa tana nuna abin da aka sayar, nawa, da ko ya ƙidaya. Sayarwar da ta ƙidaya tana nunawa a matsayin an ƙidaya, a cikin kalmomi masu sauƙi.",
  "training.lessons.staff-pos-till-sales.step3": "Wani lokaci ana RIƘE sayarwa maimakon haka: til ya sayar da wani abu da manhajar ba za ta iya daidaita shi da samfur tukuna ba. Ba a fitar da komai daga kaya ba — sayarwar tana jira har mai shi ko manaja ya daidaita wannan abu sau ɗaya (allon daidaitawa). Bayan haka, tana ƙidayawa, kuma sayarwa ta gaba na abu ɗaya tana daidaita da kanta.",
  "training.lessons.staff-pos-till-sales.step4": "Idan sayarwar da aka riƙe game da wani abu da ka sayar yanzu ne, faɗa wa manajanka ko mai shi — daidaitawa ɗaya mai sauri tana gyara shi har abada. Kada ka taɓa daidaita kayan da hannu don rama sayarwar da aka riƙe; wannan zai ƙidaya shi sau biyu da zarar an daidaita shi.",
  "training.lessons.staff-pos-till-sales.title": "Lokacin da til ya sayar da shi, kayanka yana motsawa da kansa",
  "training.module.pos": "Haɗin til (POS)",
  "plansLib.businessIncludes.tillConnections": "Haɗin til (POS)",
