  "pos.events.heldPlanNote": "Wasu tallace-tallace a ƙasa sun iso yayin da wannan shago ba ya kan tsarin Business. An riƙe su cikin aminci kuma ba a ƙidaya komai ba. Yanzu da shagon yana kan Business, za ka iya ƙidaya su.",
  "plansLib.includes.movements": "Motsin kaya da cikakken tarihi",
