  "print.senderAddressLabel": "Adireshinka (mai aikawa)",
  "print.shippingNote": "Idan odar tana da adireshin aikawa, yana cika daga odar. Abin da ka rubuta a nan ana buga shi sau ɗaya kuma ba a taɓa ajiye shi ba.",
  "print.carrier.title": "Lakabin mai jigilar ku",
  "print.carrier.desc": "Ku sayi kuɗin aikawa daga mai jigila, kamar yadda kuke yi a yau — wannan manhaja ba ta taɓa sayar da kuɗin aikawa ba, don haka farashin da kuke biya koyaushe farashin mai jigila ne da kansa. Ajiye fayil ɗin lakabi a nan kuma zai kasance a kan wannan oda har abada: rikodinku, a hannu idan wani abu ya faru.",
  "print.carrier.none": "Ba a ajiye wani lakabin mai jigila don wannan oda ba tukuna.",
