  "print.carrier.tooLarge": "Wannan fayil ya yi girma sosai — fayil ɗin lakabi dole ya kasance ƙasa da 25 MB.",
  "print.carrier.badType": "Wannan fayil ba zai yi aiki ba — zaɓi lakabin PDF, PNG, ko JPG.",
  "print.carrier.failed": "Ba a iya ajiye lakabin ba. Babu abin da ya canza — sake gwadawa.",
  "print.carrier.removeConfirm": "Cire lakabin mai jigila da aka ajiye don wannan oda? Za a goge fayil ɗin daga manhaja.",
  "print.carrier.pdfHint": "Wannan lakabi PDF ne. Yana buɗewa da girman sa na gaske — buga daga mai dubawa kuma zai fito daidai 4×6.",
  "print.carrier.pickOrderFirst": "Zaɓi oda a sama, sannan ajiye lakabin mai jigilar sa a nan.",
  'print.carrier.pickFirstTap': "Da farko zaɓi oda a sama — sa'an nan wannan maɓalli zai ajiye lakabin mai ɗaukar kaya a cikin wannan odar.",
  "print.style.title": "Salon takarda",
  "print.style.desc": "Ku mai da takardunku naku. Waɗannan zaɓuɓɓuka suna ƙawata daftarin ku, rasitin ku, takardar kwali, takardun dawowa, takardun samfur, takardun ƙidaya, da jerin ɗauka — kuma ana tunawa da su don kasuwancin ku.",
  "print.style.logoLabel": "Tambarin ku",
  "print.style.logoOn": "Tambarin ku yana bugawa a saman takardun ku.",
  "print.style.logoOff": "Babu tambari tukuna. Ƙara ɗaya a Saituna kuma zai bugawa a saman takardun ku.",
  "print.style.color": "Buga da launi",
  "print.style.colorHint": "A kunne: tambarin ku, hotuna, da firam ɗin ku suna bugawa da launi. A kashe: komai yana bugawa da baƙi-da-fari mai tsabta, yana adana tawada.",
  "print.style.font": "Harafin takarda",
  "print.style.fontDefault": "Tsohon manhaja",
  "print.style.border": "Firam ɗin shafi",
