  "print.style.removeImage": "Cire hoto",
  "print.style.save": "Ajiye salon takarda",
  "print.style.saved": "An ajiye salon takarda.",
  "print.style.saveFailed": "Ba a iya ajiye salon ba. Babu abin da ya canza — sake gwadawa.",
  "print.style.imageWidth": "Faɗin hoto",
  "print.style.imageLength": "Tsawon hoto",
  "print.style.imageSizeHint": "Faɗi shi ne sashen faɗin shafi da hoto ya mamaye; tsawo shi ne mafi tsayin da za a iya bugawa. Bar akwatin babu komai don girman da aka saba.",
  "print.printedAt": "An buga a ranar {date} da ƙarfe {time}",
  "print.style.previewText": "Dila mai launin ruwan kasa mai sauri yana tsalle a kan kare mai kasala. 1234567890",
  "training.lessons.owner-shipping-labels.step1": "Cibiyar Bugu tana da salon Alamar jigila a cikin shirye-shiryen biyu: zaɓi odar abokin ciniki kuma buga alama 4×6 tare da suna da adireshin mai saya da kasuwancinka a matsayin mai aikawa.",
  "training.lessons.owner-shipping-labels.step2": "Wannan alama fari ce, kamar kowace takardar abokin ciniki: tana ɗauke da sunan kasuwancinka kaɗai — ba sunan wannan manhajar ba har abada — don haka kunshi daga shagonka ya yi kama da ya fito daga shagonka.",
  "training.lessons.owner-shipping-labels.step3": "Adireshin abokin ciniki ana ajiye shi tare da odarsa na kwanaki 90 bayan odarsa ta ƙarshe, kuma lakabin yana farawa daga adireshin da aka ajiye na oda idan tana da shi; adireshin da aka buga a lokacin bugu don lakabi na sau ɗaya ba a ajiye shi baya. Sunan har yanzu yana cikewa daga oda don lakabin ya yi daidai da takardun.",
  "training.lessons.owner-shipping-labels.step4": "Wannan alama tana bugawa ta haɗin guda huɗu daidai da kowace alama — Bluetooth, Wi-Fi, Ethernet da USB — kuma na’urar buga zafi 4×6 ita ce girmanta na yau da kullun.",
  "training.lessons.owner-shipping-labels.step5": "Kun sayi kuɗin aikawa daga mai jigila a maimakon haka? A cikin wannan sashe ɗaya za ku iya lodawa fayil ɗin lakabin mai jigila — PDF, PNG, ko JPG — kuma zai kasance a ajiye a kan odar har abada: rikodinku, a hannu idan wani abu ya faru. Ana bugawa da girman sa na gaske 4×6. Manhajar ba ta taɓa sayar da kuɗin aikawa ba, don haka farashin mai jigila shi ne farashi guda ɗaya — kuma koyaushe farashin da ya dace.",
  "training.lessons.owner-shipping-labels.title": "Alamun jigila don odar abokan ciniki",
  "training.lessons.print-shipping-label.step1": "Idan oda ta shirya don aikawa, buɗe Cibiyar Bugu, zaɓi salon Alamar jigila, sannan zaɓi odar abokin ciniki. Sunan mai saya yana cika daga oda.",
  "training.lessons.print-shipping-label.step2": "Duba adireshin da kunshin ke zuwa. Lokacin da oda ta ɗauki adireshin abokin ciniki — ana ajiye shi na kwanaki 90 bayan odarsa ta ƙarshe — yana cikewa a gare ka; adireshin da ka buga a lokacin bugu ba a ajiye shi baya, don haka duba lambar gidan waya da layin ƙarshe a hankali kafin ka buga.",
  "training.lessons.print-shipping-label.step3": "Sunan kasuwancinka yana buguwa a sama a matsayin mai aikawa. Idan kana son adireshinka ma ya kasance a kan alamar, buga shi a cikin akwatin adireshin mai aikawa; bar shi fanko idan ba ka son ya bayyana.",
  "training.lessons.print-shipping-label.step4": "Buga a kan alama 4×6 — na’urar buga alama mai zafi ita ce zaɓi na yau da kullun — ko a kan kowace na’urar bugu ta maɓallin bugu na bincike. Manna alamar a kwance a kan kunshin, a inda ba za ta naɗe a gefe ba.",
  "training.lessons.print-shipping-label.step5": "Idan an sayi kuɗin aikawa daga mai jigila, ajiye fayil ɗin lakabin su a kan odar a maimakon haka: loda PDF, PNG, ko JPG da mai jigila ya ba ku a sashen Lakabin mai jigilar ku. Yana kasancewa a kan odar a matsayin rikodinku kuma ana bugawa da girman sa na gaske 4×6 — kuma lakabin adireshin manhajar da kanta koyaushe yana nan lokacin da kuka fi son amfani da shi.",
  "training.lessons.print-shipping-label.title": "Buga alamar jigila",
  "pos.provider.clover": "Clover",
  "pos.provider.toast": "Toast",
