  "apiErrors.productLimit.planIncludesLimitProducts": "Wannan tsarin ya haɗa da samfura {limit} kuma {used} sun riga sun kasance cikin kundin. Share samfurin da ba ka buƙata kuma don 'yantar da wuri, ko matsa zuwa Business don samfura marasa iyaka.",
