  "apiErrors.siteLimit.planIncludesLimitSites2": "Wannan tsarin ya haɗa da shafuka {limit}. Shelf, akwatuna da motoci a cikin shafi ba sa ƙidaya, kuma har yanzu kana iya ƙara su.",
