  "apiErrors.staffEmailChange": "Yi amfani da gyaran imel a shafin Ma'aikata don canza imel ɗin ma'aikacin ƙungiya — yana motsa asusunsa, sauran shagunansa da tarihin gwajinsa tare da shi. Gyara na yau da kullun zai bar su a ƙarƙashin tsohon adireshin.",
  "apiErrors.staffExists.anotherTeamMemberBusiness": "Wani ma'aikacin ƙungiya a cikin wannan kasuwancin ya riga ya na amfani da wannan imel ɗin.",
