  "apiErrors.staffLimit.planIncludesLimitAdditional": "Wannan tsarin ya haɗa da ƙarin ma'aikata {limit}. 'Yantar da kujera ko matsa zuwa Business don ma'aikata marasa iyaka.",
  "apiErrors.staffNoAccount": "Wannan ma'aikacin ƙungiyar bai riga ya yi rajista ba, don haka babu kalmar sirri da za a sake saita. Za su saita kalmar sirrinsu lokacin da suka karɓi gayyatar.",
  "apiErrors.staffNotFound": "Wannan ma'aikacin ƙungiyar ba ya cikin wannan kasuwancin.",
  "apiErrors.storeAlreadyConnected.providerAccountAlreadyConnected": "Wannan asusun {provider} ya riga ya haɗa da wani filin aiki a nan. Cire haɗin sa a can da farko.",
  "apiErrors.storeAlreadyConnected.shopifyStoreAlreadyConnected": "Wannan shagon Shopify ya riga ya haɗa da wani filin aiki a nan. Cire haɗin sa a can da farko.",
