  "apiErrors.supportRateLimited": "Ka aika rahotanni da yawa a yau. Da fatan za a jira har gobe don aika ƙari, don a iya karanta kowane rahoto yadda ya kamata.",
  "apiErrors.toastCredentialsMissing": "Wannan haɗin Toast ba shi da takardun shaidarsa — sake haɗa Toast.",
