  "profile.nameLabel": "Sunanka",
  "profile.nameHint": "Wannan sunan yana maye gurbin kalmar Mai gida a ko'ina — kusa da hotonka, a cikin Saƙonni, da kuma a allon ƙungiyarka. Bar shi babu komai idan kana son a kira ka Mai gida.",
  "profile.nameSave": "Ajiye suna",
