  "profile.nameCleared": "An share sunanka — yanzu ana kiran ka Mai gida kuma.",
  "profile.approvalsTitle": "Hotuna da ke jiran amincewarka",
  "profile.approvalsDesc": "Hoton ɗan ƙungiya ba ya bayyana a ko'ina har sai ka amince da shi. Idan ba ka amince ba, za a nemi mutumin ya zaɓi wani hoto.",
  "profile.approve": "Amince",
  "profile.decline": "Kada a amince",
