  "plansLib.includes.profilePhotos": "Hotunan bayanin martaba ga duk ƙungiyarka, mai gida ne ya amince da su",
  "apiErrors.notFound.photoFound": "Ba a sami hoton ba.",
  "apiErrors.profileOwnerNameOnly": "Mai gidan kasuwanci kaɗai ne zai iya saita sunan mai gida.",
  "apiErrors.profilePhotosApproveOwnerOnly": "Mai gidan kasuwanci kaɗai ne zai iya amincewa da hotunan ƙungiya.",
  "apiErrors.profilePhotosNoneWaiting": "Wannan ɗan ƙungiya ba shi da hoto da ke jiran amincewa.",
  "apiErrors.profileOwnerNameTooLong": "Ka riƙe sunanka a haruffa 80 ko ƙasa da haka.",
  "training.lessons.your-profile-photo.title": "Hoton bayanin martabarka",
  "training.lessons.your-profile-photo.step1": "Hotonka yana bayyana kusa da sunanka a saman manhajar, a shafin Ma'aikata, da kusa da saƙonninka — da zarar mai gida ya amince da shi. Har zuwa lokacin, haruffan farko na sunanka kaɗai suke bayyana.",
  "training.lessons.your-profile-photo.step2": "Buɗe Saituna ka nemo Hoton bayanin martabarka. Zaɓi hoton kanka ka aika shi. Yana zuwa ga mai gida domin amincewa — ba ya bayyana a ko'ina yayin da yake jira.",
  "training.lessons.your-profile-photo.step3": "Idan mai gida ya amince da shi, ƙararrawarka za ta yi ƙara kuma hotonka zai fara bayyana. Idan ba a amince ba, zaɓi wani hoto daban ka aika wannan a maimakonsa.",
  "training.lessons.your-profile-photo.step4": "Canza hotonka yana aiki haka nan: sabon yana jiran amincewa, kuma hotonka na yanzu yana nan har sai an amince da sabon. Idan ba a amince da canjin ba, za ka ci gaba da ɗayan naka.",
  "training.lessons.owner-profile-photos.title": "Hotunan bayanin martaba da sunanka",
  "training.lessons.owner-profile-photos.step1": "Hoton kowane mutum yana bayyana kusa da sunansa a saman manhajar, a shafin Ma'aikata naka, da kusa da saƙonninsa. Hoton ɗan ƙungiya ba ya bayyana a ko'ina har sai ka amince da shi — amincewa naka ne kai kaɗai, kuma babu wanda zai iya amincewa da hoton kansa.",
  "training.lessons.owner-profile-photos.step2": "Idan wani ya aika hoto, ƙararrawarka za ta yi ƙara. Buɗe shafin Ma'aikata don ganinsa, sannan zaɓi Amince ko Kada a amince. Idan ba ka amince ba, ana gaya wa mutumin ya zaɓi wani hoto.",
  "training.lessons.owner-profile-photos.step3": "Idan mutum ya canza hotonsa, sabon yana jiran amincewarka haka nan. Hotonsa na yanzu yana nan yayin da yake jira — kuma yana nan idan ba ka amince da canjin ba.",
  "training.lessons.owner-profile-photos.step4": "Hotonka na kanka ba ya buƙatar amincewa: saita shi a Saituna, a ƙarƙashin Hoton bayanin martabarka. Kat ɗin nan kuma yana ɗauke da sunanka — sunan da ka saita a can yana maye gurbin kalmar Mai gida a ko'ina da ƙungiyarka take ganinsa, a manhajar da a cikin Saƙonni.",
  "payroll.dd.corrected": "Form da aka gyara",
  "payroll.dd.correctedDone": "An aika bayananka da aka gyara ga mai shi.",
  "payroll.dd.correctionNotice": "Mai shi ya mayar maka da fom ɗinka domin ka gyara shi. Duba kowace lamba, sa hannu, kuma sake aikawa.",
  "payroll.dd.correctionWaiting": "An mayar — ana jiran fom ɗinsu da aka gyara",
  "payroll.dd.fixHelp": "Idan lamba ta yi kuskure, gyara bayananka ka sake aika fom ɗin. Sabon fom ɗinka da ka sa hannu zai maye gurbin tsohon, kuma za a gaya wa mai shi cewa an gyara shi.",
  "payroll.dd.fixMistake": "Gyara kuskure",
  "payroll.dd.form.historyTitle": "Fom-fom da aka sa hannu a baya",
  "payroll.dd.form.ownerOnlyNote": "Kai kaɗai, mai shi, za ka iya buɗe wannan fom. Yana nuna cikakkun lambobin banki da sa hannun memba.",
  "payroll.dd.form.replacedOn": "An maye gurbin a {date}",
