  "payroll.dd.sendBack": "Mayar domin gyara",
  "payroll.dd.sendBackDone": "An mayar zuwa ga {name} — yanzu za su iya gyara bayanansu.",
  "payroll.dd.signHelp": "Rubuta sunanka, sannan zaɓi yadda sa hannunka zai yi kama. Wannan shine sa hannunka na lantarki — ana sanya shi a kan fom ɗin ajiyar kai tsaye naka daidai kamar yadda aka nuna a nan.",
  "payroll.dd.signName": "Sunanka — ya zama sa hannunka",
  "payroll.dd.signStyle": "Salon sa hannu",
  "payroll.dd.signTitle": "Sa hannu a fom ɗinka",
  "payroll.dd.signedAs": "An sa hannu a matsayin {name} a {date}",
  "payroll.dd.styleItalic": "Italik",
  "payroll.dd.styleScript": "Rubutun hannu mai gudana",
  "payroll.dd.styleSimple": "Mai sauƙi da bayyananne",
  "payroll.dd.viewForm": "Duba fom da aka sa hannu",
  "payroll.profile.address": "Adireshin gida",
  "payroll.profile.name": "Cikakken suna",
  "payroll.profile.noAddress": "Babu adireshin gida a rubuce tukuna.",
  "payroll.profile.note": "Ana amfani da waɗannan bayanai don albashinka da fom-fom ɗin harajinka, kuma kai kaɗai za ka iya ganin su a nan. Idan wani abu yana buƙatar canji, tambayi mai shi ko manajanka — su ne za su iya sabunta su.",
  "payroll.profile.title": "Bayananka da ke rubuce",
  "payroll.stubs.print": "Buga / sauke",
  "apiErrors.invalidValue.signYourForm": "Rubuta sunanka don sa hannu a fom ɗin ajiyar kai tsaye naka.",
  "apiErrors.invalidValue.chooseSignatureStyle": "Zaɓi salon sa hannu.",
  "apiErrors.invalidValue.noDdDetailsYet": "Wannan memba na ƙungiyar bai aika bayanansa ba tukuna.",
  "training.lessons.owner-dd-setup.step5": "Abin da ya iso shine fom da aka rufe kuma aka sa hannu: daga layin mutumin a Biyan Albashi za ka iya buɗe shi don karanta cikakkun lambobi, buga shi ko adana kwafi — ba za ka taɓa iya gyara shi ba. Idan lamba ta yi kama da kuskure, mayar da fom ɗin: mutumin da kansa ya gyara ya sake sa hannu, fom ɗinsa da aka gyara ya maye gurbin tsohon, kuma fom ɗin baya ya kasance a cikin rubutu tare da ranar maye gurbinsa.",
  "payroll.profile.ownerNote": "Waɗannan bayanan ka ne da ke cikin fayil, daga asusunka. Kai kaɗai za ka iya ganin su a nan — kuma tun da naka ne, za ka iya sabunta su a nan duk lokacin da suka canza.",
