  "staffLib.perm.staffClockBoard": "Allon agogo da fita da aka rasa",
  "staffLib.perm.staffCallins": "Kiran aiki",
  "staffLib.area.clockAccess": "Allon agogo da kiran aiki",
  "staff.memberDialog.clockAccessHint": "Manajoji kawai — alamu biyu daban-daban. Allon agogo da fita da aka rasa yana ba wannan manaja damar ganin bayanan agogon ƙungiya da gyara bayanan lokaci daga shafin Ma’aikata. Kiran aiki yana ba wannan manaja damar buɗe tagogin kiran aiki, barin wani ya yi aiki lokacin da ba shi da jadawali. Waɗannan alamu ba sa yin komai ga ma’aikata.",
