  "staff.callIn.title": "Kiran aiki da fita daga aiki da aka rasa",
  "staff.callIn.desc": "Kira wani lokacin da ba shi da jadawali, ka gyara bayanan lokaci lokacin da aka manta fita daga aiki. Tagar kiran aiki tana kasancewa a buɗe har sai mutumin ya fita daga aiki.",
