  "staff.timeFix.open": "Gyara lokuta",
  "apiErrors.clockGate.notScheduled": "Ba a tsara ka yi aiki yanzu ba, kuma babu tagar kiran aiki a buɗe gare ka.",
  "apiErrors.clockAdmin.callinsNotGranted": "Mai shi kaɗai, ko manajan da mai shi ya amince masa da kiran aiki, ne zai iya yin hakan.",
  "apiErrors.clockAdmin.boardNotGranted": "Mai shi kaɗai, ko manajan da mai shi ya amince masa da allon agogo da fita da aka rasa, ne zai iya yin hakan.",
  "apiErrors.clockAdmin.ownerOnlyForManager": "Mai shi kawai zai iya sarrafa kiran aiki da bayanan lokacin manaja.",
  "apiErrors.clockFix.outBeforeIn": "Lokacin fita daga aiki dole ne ya kasance bayan lokacin shiga aiki.",
  "apiErrors.clockFix.breakOutside": "Lokutan hutu dole ne su kasance tsakanin lokacin shiga aiki da lokacin fita daga aiki.",
  "apiErrors.clockFix.invalidTime": "Aika kowane lokaci a matsayin kwanan wata da lokaci ingantattu.",
  "apiErrors.notFound.timeEntryFound": "Ba a sami bayanin lokaci ba.",
  "training.lessons.mgr-clock-callin.title": "Kiran aiki da gyaran agogo",
  "training.lessons.mgr-clock-callin.step1": "Mai shi zai iya ba manaja alamu biyu daban-daban. Da Kiran aiki, za ka iya buɗe tagar kiran aiki ga memba na ma’aikata, kuma da Allon agogo da fita da aka rasa, za ka iya ganin allon agogon ƙungiya da gyara bayanan lokaci daga shafin Ma’aikata. Kowane alama yana aiki shi kaɗai — manaja zai iya riƙe ɗaya ba tare da ɗayan ba.",
  "training.lessons.mgr-clock-callin.step2": "Tagar kiran aiki tana barin mutum ya shiga ya fara aiki lokacin da babu juyawar da ta rufe shi. Buɗe ta daga shafin Ma’aikata, a katin Kiran aiki da fita daga aiki da aka rasa.",
  "training.lessons.mgr-clock-callin.step3": "Tagar tana kasancewa a buɗe har sai mutumin ya fita daga aiki — sai kuma al’adar mintuna 10 na jinkiri kafin fita daga asusu — ko har sai kai ko mai shi kun rufe ta da wuri. Babu abin da ke rufe ta da kansa.",
  "training.lessons.mgr-clock-callin.step4": "Lokacin da wani ya manta fita daga aiki, bayanin sa yana samun alama a shafin Ma’aikata da a cikin Albashi da zarar juyawar da aka tsara ta ƙare, kuma ana sanar da kai da mai shi. Bayanin yana ci gaba da ƙidaya har sai an gyara shi.",
  "training.lessons.mgr-clock-callin.step5": "Gyara bayanin daga shafin Ma’aikata: saita shiga aiki, fita daga aiki, da lokutan hutu. Manaja yana gyara bayanan ma’aikata kawai — bayanan manaja kansa mai shi ne ke gyara su.",
  "staffLib.perm.staffDocuments": "Takardun ma’aikata",
  "staffLib.area.documentsAccess": "Takardun ma’aikata",
  "staff.memberDialog.documentsAccessHint": "Manajoji kaɗai — da wannan alamar, wannan manajan zai iya buɗe fayilolin takardun membobin ma’aikata: takardun da ake ajiye wa kowane mutum, kamar fam ɗin W-4, neman aiki da kwafin katin shaida. Za a nemi tabbatarka da farko — waɗannan fayiloli suna ɗauke da lambobin Tsaron Jama’a da ranakun haihuwa. Wannan alamar ba ta yin komai ga ma’aikata.",
  "staff.documentsWarning.body": "Wannan mutumin zai iya ganin bayanan sirri game da membobin ma’aikatanka, ciki har da lambobin Tsaron Jama’a da ranakun haihuwa.",
  "staff.documentsWarning.confirm": "I, na fahimta",
  "staff.documents.title": "Takardun ma’aikata",
  "staff.documents.desc": "Takardun da kake ajiye wa kowane mutum — fam ɗin W-4, neman aiki, fam ɗin haraji, kwafin katin shaida. Kai kaɗai, da manajan da ka ba shi alamar Takardun ma’aikata, za ku iya buɗe waɗannan fayiloli.",
  "staff.documents.open": "Takardu",
  "staff.documents.fileCount": "{count} a cikin fayil",
  "staff.documents.noneOnFile": "Babu komai a cikin fayil",
  "staff.documents.dialogDesc": "Ana ajiye kowane ɗorawa — sabon salo ba ya taɓa maye gurbin na da.",
  "staff.documents.titleLabel": "Take",
