  "nav.xstoreMessages": "Saƙonni Tsakanin Shaguna",
  "plansLib.businessIncludes.xstoreMessages": "Saƙonni Tsakanin Shaguna — dukan ƙungiyar ku, a cikin duk kasuwancin ku",
  "xstore.title": "Saƙonni Tsakanin Shaguna",
  "xstore.help": "Kowa a cikin wannan asusu, daga duk kasuwancin ku, a cikin akwatin saƙo guda ɗaya. Aika saƙo ga kowa a cikinsu a nan — rubutu ko murya, tare da alamun an kai da an karanta. Saƙonnin cikin shagon ku sun kasance kamar yadda suke.",
  "xstore.empty": "Babu hira tukuna. Fara wata da Sabon saƙo.",
  "xstore.noPeople": "Babu wani wanda za a aika wa saƙo tukuna. Mutane suna bayyana a nan da zarar sun shiga ɗaya daga cikin kasuwancin ku kuma sun shiga asusu.",
  "xstore.deliveredLabel": "An Kai",
  "apiErrors.planGated.crossStoreMessagesPartBusiness": "Saƙonni Tsakanin Shaguna wani ɓangare ne na shirin Business.",
  "apiErrors.invalidValue.personNotPartAccount": "Wannan mutumin ba ɓangare ba ne na wannan asusu.",
  "training.lessons.owner-xstore-messages.title": "Saƙonni a duk shagunan ku, ga masu shago",
  "training.lessons.owner-xstore-messages.step1": "Saƙonni Tsakanin Shaguna akwatin saƙo ne na biyu, dabam da Saƙonni. Saƙonni na shagon da kuke ciki ne; wannan ƙofar tana isa ga kowa a cikin asusun ku, a cikin kowane kasuwanci da kuka mallaka — har guda biyar.",
  "training.lessons.owner-xstore-messages.step2": "Buɗe Saƙonni Tsakanin Shaguna daga menu kuma fara hira da kowa a cikin jerin. Jerin yana nuna kowane memba na ƙungiya daga duk kasuwancin ku da ya shiga, tare da shagunan da suke aiki a ciki.",
  "training.lessons.owner-xstore-messages.step3": "Hotuna suna tafiya tare: kowane mutum yana nuna hoton bayanan martabarsa da aka amince da shi, ko haruffan farko na sunansa idan ba shi da shi. Kowane saƙo yana ɗauke da ranar da lokacin da aka aika shi.",
  "training.lessons.owner-xstore-messages.step4": "A ƙarƙashin saƙonnin ku, kuna iya ganin An Kai da zarar saƙo ya isa, da An Karanta da zarar ɗayan mutumin ya buɗe hirar. Bayanan murya suna aiki a nan ma, kamar yadda suke a cikin Saƙonni.",
  "training.lessons.owner-xstore-messages.step5": "Hirarraki a nan na sirri ne ga mutane biyun da ke cikinsu. Kula da Saƙonnin cikin shago ba ya isa zuwa wasu shaguna.",
  "training.lessons.mgr-xstore-messages.title": "Saƙonni a duk shagunan ku, ga manajoji",
  "training.lessons.mgr-xstore-messages.step1": "Saƙonni Tsakanin Shaguna yana isa ga kowa a cikin wannan asusu, a cikin kowane kasuwanci — ba shagon da kuke ciki kaɗai ba. Yana cikin menu, dabam da Saƙonni.",
  "training.lessons.mgr-xstore-messages.step2": "Fara hira daga jerin: kowane memba na ƙungiya da ya shiga yana nan, tare da shagunan da suke aiki a ciki kusa da sunayensu.",
  "training.lessons.mgr-xstore-messages.step3": "Aika rubutu, ko naɗi bayanin murya. Kafin a aika bayanin murya, kuna iya sake saurara, jefar da shi, ko aika shi — kamar yadda yake a cikin Saƙonni.",
  "training.lessons.mgr-xstore-messages.step4": "Saƙonnin ku suna nuna An Kai idan sun isa da An Karanta idan ɗayan mutumin ya buɗe hirar. Hoton da ke kusa da kowane suna hoton bayanan martabar mutumin ne da aka amince da shi.",
  "training.lessons.staff-xstore-messages.title": "Saƙonni a duk shagunan ku",
  "training.lessons.staff-xstore-messages.step1": "Saƙonni Tsakanin Shaguna shi ne inda za ku iya isa ga kowa a cikin wannan asusu, a cikin kowane kasuwancin mai shago — tambaya ga wani shago ba ta buƙatar jira kuma.",
  "training.lessons.staff-xstore-messages.step2": "Buɗe shi daga menu, zaɓi mutumin, kuma rubuta. Idan mutumin da kuke buƙata bai cikin jerin, bai shiga tukuna ba — zai bayyana da zarar ya shiga.",
  "training.lessons.staff-xstore-messages.step3": "Kuna iya aika bayanan murya a nan ma: naɗa, sake saurara, sannan aika ko jefar. Kowane saƙo yana nuna ranar da lokacin da aka aika shi.",
  "training.lessons.staff-xstore-messages.step4": "Idan kun aika saƙo, yana nuna An Kai da zarar ya isa, da An Karanta da zarar ɗayan mutumin ya buɗe hirar. Hira ta sirri ce gare ku da ɗayan mutumin.",
  "nav.invoices": "Daftarin masu samarwa",
  "nav.waste": "Rajistar ɓarna",
  "nav.expiry": "Karewa da ranaku",
  "nav.allergens": "Abubuwan aleji",
  "nav.tempLogs": "Rajistar zafin yanayi",
  "nav.eightySix": "Allon abubuwan da suka ƙare",
  "nav.transfers": "Canja wuri",
  "nav.staffMeals": "Abincin ma'aikata",
  "nav.menu": "Binciken menu",
  "nav.variance": "Bambanci",
  "nav.prep": "Takardun shirye-shirye",
  "nav.ledger": "Fitarwa zuwa lissafi",
  "plansLib.businessIncludes.restaurantOps": "Ayyukan gidan abinci — daftarin masu samarwa da daidaito ta hanyoyi uku, rajistar ɓarna, ranakun karewa da teburin abubuwan aleji",
  "plansLib.businessIncludes.restaurantDaily": "Kayan aikin gidan abinci na yau da kullun — rajistar zafin yanayi, allon abubuwan da suka ƙare, takardun shirye-shirye, binciken menu, bambanci da fitarwa zuwa lissafi",
  "plansLib.businessIncludes.restaurantKitchen": "Gidan abinci, Ɗakin girki da girke-girke — girke-girke masu rage sinadarai kai tsaye da ainihin farashin abinci, takardun shirye-shirye, samar da rukuni da binciken menu",
  "plansLib.businessIncludes.restaurantStock": "Gidan abinci, Kaya da oda — matakan ajiya (par), jagorar oda da canja wuri tsakanin wurare, da kuma takardun kirga a cikin tsarin shiryawa",
  "plansLib.businessIncludes.restaurantMoney": "Gidan abinci, Daftari da kuɗi — daftarin masu samarwa da daidaito ta hanyoyi uku, faɗakarwar farashi, bambanci da fitarwa zuwa lissafi, da kuma takardun kiredit na masu samarwa",
  "plansLib.businessIncludes.restaurantSafety": "Gidan abinci, Tsaron abinci — rajistar zafin yanayi, ranakun karewa bisa tsarin wanda ya kusa karewa a fara amfani, tambarin rana da teburin abubuwan aleji, da log na zafin jiki da aka cika don fayil ɗin amincin abinci",
  "plansLib.businessIncludes.restaurantFloor": "Gidan abinci, Filin da baƙi — allon abubuwan da suka ƙare da rajistar ɓarna",
  "plansLib.businessIncludes.restaurantTeam": "Gidan abinci, Ƙungiya da wuri — abincin ma’aikata",
