  "menu.subtitle": "Kowane abinci da aka sanya bisa yadda ya sayar da yadda ya samu a cikin lokacin: taurari suna samu kuma suna sayarwa, dawakan ja suna sayarwa, abubuwan mamaki suna samu, karnuka ba sa yin ɗayan.",
