  "variance.subtitle": "Ga kowane samfur: abin da girke-girke suka ce ya kamata ya bar shiryayyen wuri, kusa da abincin ma'aikata, ɓarna, da duk wani abin da ya fita. Abin da ya rage ba tare da bayani ba shi ne bambancin da za a je a bayyana.",
