  "prep.title": "Takardun shirye-shirye",
  "prep.subtitle": "Samar da rukuni a sama; a ƙasa, takardar shirye-shirye — ga kowane abinci, sau nawa ake yi da za su dawo da shi zuwa matakin ajiya (par), da abin da waɗannan sau suke ɗauka daga shiryayyen wuri.",
