  "exportsLib.restaurantLedger.title": "Littafin gidan abinci",
  "exportsLib.restaurantLedger.description": "Sayayya da aka karɓa, ɓarna, abincin ma'aikata da raguwar girki a littafi ɗaya: sashe, rana, abu, yawa, kuɗin naúra, jimillar kuɗi da nassoshi.",
