  "training.lessons.owner-restaurant-ops.title": "Ayyukan gidan abinci, don masu shi",
  "training.lessons.owner-restaurant-ops.step1": "Daftarin masu samarwa suna zaune a kusurwar Gidan abinci. Shigar da abin da mai samarwa ya lissafa, an haɗa da odar sayensa, kuma manhajar tana bincika shi ta hanyoyi uku — an oda, an karɓa kuma an lissafa, kusa da kusa — kuma tana yi wa kowane layi da ya yi ƙasa, ya yi yawa, ko aka lissafa shi da farashi daban alama.",
  "training.lessons.owner-restaurant-ops.step2": "Lokacin da layin daftari ya lissafa samfur da farashin da ya bambanta da kuɗin da aka rubuta, faɗakarwar farashi tana buɗewa a shafin daftari. Karɓar faɗakarwa yana sabunta kuɗin samfur zuwa farashin da aka lissafa; yin watsi da ita yana barin kuɗin kamar yadda yake.",
  "training.lessons.owner-restaurant-ops.step3": "Rajistar ɓarna tana rubuta duk abin da ɗakin girki ya jefar, tare da dalili — lalacewa, samar da yawa, kuskuren shirye-shirye, dawo da shi, zubewa, ko wani abu — kuma yin rajistarsa yana ɗaukar kayan ajiya daga shiryayyen wuri da kansa. Rukunin karewa ana jera su wanda ya fara karewa ya fara fita, don ranar amfani-da-shi ta farko ta fara amfani, kuma za ka iya buga alamun ranaku don rukunin da ka yi wa alama.",
  "training.lessons.owner-restaurant-ops.step4": "Teburin abubuwan aleji yana lissafa abubuwan aleji na kowane abinci daga sinadaran girkensa, da abubuwan aleji tara mafi girma, don a amsa tambayar baƙo daga bayanin da aka ajiye, ba daga ƙwaƙwalwa ba. Rajistar zafin yanayi, allon abubuwan da suka ƙare da abincin ma'aikata a buɗe suke ga duk ƙungiyar — babu alama da ake buƙata — domin rajista ta yau da kullun tana aiki ne kawai lokacin da kowa zai iya yin ta.",
  "training.lessons.owner-restaurant-ops.step5": "Binciken menu yana sanya kowane abinci bisa yadda ya sayar da yadda ya samu: taurari, dawakan ja, abubuwan mamaki da karnuka. Shafin bambanci yana kwatanta abin da girke-girke suka ce ya kamata ya bar shiryayyen wuri da abincin ma'aikata, ɓarna da duk wani abin da ya fita — abin da ya rage ba tare da bayani ba ne. Fitarwa zuwa lissafi tana tara sayayya da aka karɓa, ɓarna, abincin ma'aikata da raguwar girki zuwa littafi ɗaya don littattafanka.",
  "training.lessons.staff-restaurant-daily.title": "Halayen ɗakin girki na yau da kullun",
  "training.lessons.staff-restaurant-daily.step1": "Lokacin da aka jefar da wani abu, yi rajistarsa a rajistar ɓarna a rana ɗaya: abin da yake, nawa, da dalilin — lalacewa, samar da yawa, kuskuren shirye-shirye, dawo da shi, zubewa, ko wani abu. Yin rajistarsa yana ɗaukar kayan ajiya daga shiryayyen wuri da kansa; ba ka gyara kayan ajiya daban.",
  "training.lessons.staff-restaurant-daily.step2": "Yi rajistar kowane zafin firji, friza da na riƙe zafi lokacin da ka bincika shi. Rajistar tana ajiye sunanka da lokacin, kuma tana yi wa kowane karatu da yake wajen iyakar aminci alama — rubuta abin da ka yi game da shi a matsayin matakin gyara.",
  "training.lessons.staff-restaurant-daily.step3": "Allon abubuwan da suka ƙare shi ne abin da ya ƙare, yanzu. Sanya abu a lokacin da ya ƙare, don duk ƙungiyar ta sani nan take, kuma cire shi lokacin da ya dawo — allon yana ajiye wanda ya cire shi da yaushe.",
  "training.lessons.staff-restaurant-daily.step4": "Lokacin da ƙungiyar ta ci, rubuta shi a matsayin abincin ma'aikata. Kowane abinci yana ɗaukar abincinsa daga shiryayyen wuri kuma yana amfani da sinadaran girkin abincin, kamar sayarwa. Abincin ma'aikata kuɗin gaske ne na ranar, kuma yana cikin rajista.",
  "training.lessons.mgr-restaurant-invoices.title": "Daftari, rukuni da gudanar da rukuni",
  "training.lessons.mgr-restaurant-invoices.step1": "Mai shi ya amince maka da alamar 'Ƙirƙiri girke-girke', kuma tana buɗe aikin gina ɗakin girki ma: daftarin masu samarwa, rukunin karewa da samar da rukuni. Shigar da daftarin mai samarwa tare da layukansa — samfurin, yawan da kuɗin da aka lissafa — kuma haɗa shi da odar sayensa lokacin da akwai.",
  "training.lessons.mgr-restaurant-invoices.step2": "Da odar saye da aka haɗa, ana bincika daftarin ta hanyoyi uku, layi bayan layi: abin da aka oda, abin da aka karɓa da abin da aka lissafa. Layi zai iya dawo ya daidaita, ya yi ƙasa, ya yi yawa, aka lissafa shi da farashi daban, ko ba ya kan odar kwata-kwata.",
  "training.lessons.mgr-restaurant-invoices.step3": "Lokacin da farashin da aka lissafa ya bambanta da kuɗin samfur da aka rubuta, faɗakarwar farashi tana buɗewa. Karɓar faɗakarwar yana saita kuɗin samfur zuwa sabon farashin da aka lissafa; yin watsi da ita ba ya canza komai. Faɗakarwa ɗaya ce kawai a buɗe take tsayawa don daftari da samfur ɗaya a lokaci guda.",
  "training.lessons.mgr-restaurant-invoices.step4": "Karɓi kayan ajiya a matsayin rukunin karewa tare da ranar amfani-da-shi, kuma shafin karewa yana ajiye rukunin wanda ya fara karewa ya fara fita. Gudanar da rukuni yana yin girki sau da aka saita: yana amfani da sinadaran girkin kuma yana sanya samfurin shirye-shiryen da aka gama a kan shiryayyen wuri — dole a haɗa girkin da wannan samfurin shirye-shiryen da farko.",
  "training.lessons.mgr-restaurant-invoices.step5": "Idan mai samarwa ya mayar da kuɗi a kan daftari — kwali da ya lalace, isarwa da ta gaza, farashi da aka gyara — rubuta shi a matsayin takardar kiredit a shafin daftari, a kan wannan daftarin. Mai samarwa yana fitowa daga daftarin kansa, kuma takardar ana kirga ta a kan abin da har yanzu ake bi a daftari: daftarin yana nuna kiredit da aka yi amfani da shi da ragowar da ake bi. Kiredit ba zai taɓa wuce daftarinsa ba, kuma sokewar takarda tana kiyaye ta a cikin tarihi yayin da ta daina kirguwa. Buga takardar daga layinta lokacin da kake buƙata a takarda — takardar da aka buga ita ce rikodinka na bashin mai kaya, ba takardar mai kaya ba.",
  "training.lessons.mgr-restaurant-reports.title": "Binciken menu, bambanci da littattafai",
  "training.lessons.mgr-restaurant-reports.step1": "Mai shi ya amince maka da alamar 'Kuɗin abinci', kuma tana buɗe rahotannin kuɗin ɗakin girki ma: binciken menu, bambanci da fitarwa zuwa lissafi. Waɗannan adadi suna zama a cikin kasuwancin, kamar duk kuɗin abinci.",
  "training.lessons.mgr-restaurant-reports.step2": "Binciken menu yana sanya kowane abinci bisa yadda ya sayar da yadda ya samu a cikin lokacin. Taurari suna sayarwa sosai kuma suna samu sosai; dawakan ja suna sayarwa sosai amma suna samu kaɗan; abubuwan mamaki suna samu sosai amma suna sayarwa kaɗan; karnuka ba sa yin ɗayan.",
  "training.lessons.mgr-restaurant-reports.step3": "Shafin bambanci yana aiki ga kowane samfur: abin da girke-girke suka ce ya kamata ya bar shiryayyen wuri, kusa da abincin ma'aikata, ɓarna da kowane fitar kaya. Duk abin da ya rage ba tare da bayani ba ne — kuma wanda ba tare da bayani ba shi ne adadin da za a je a bayyana.",
  "training.lessons.mgr-restaurant-reports.step4": "Fitarwa zuwa lissafi littafi ɗaya ne don ɗakin girki: sayayya da aka karɓa, ɓarna, abincin ma'aikata da raguwar girki, kowane layi tare da ranarsa, yawansa da kuɗinsa, a shirye don miƙa wa wanda yake ajiye littattafanka.",
