  "nav.storefronts": "Haɗin shagunan gaba",
  "plansLib.includes.ebaySync": "Haɗin shagon gaba na eBay — tallace-tallace suna sabunta hajarku da kansu",
  "storefronts.applied": "Yi rijistar tallace-tallacen da aka riƙe",
  "storefronts.checkNow": "Duba tallace-tallace yanzu",
  "storefronts.checking": "Ana dubawa…",
