  "apiErrors.checklistsManage": "Mai shi kaɗai, ko mutumin da mai shi ya ba alamar samfuran jerin dubawa, zai iya canza samfuran jerin dubawa.",
  "apiErrors.checklistProof": "Wannan abu yana buƙatar shaidarsa kafin a yi masa alama.",
  "apiErrors.checklistName": "Ba wa jerin dubawa suna.",
  "apiErrors.checklistItems": "Ƙara aƙalla abu ɗaya zuwa jerin dubawa.",
  "apiErrors.checklistUntick": "Mutumin da ya yi alama ga wannan abu kaɗai, manaja, ko mai shi zai iya cire alamar.",
  "training.lessons.staff-checklists.title": "Yin aiki a jerin dubawa",
  "training.lessons.staff-checklists.step1": "Jerin dubawa su ne jerin da kasuwancinka ke gudana a kai — buɗewa, rufewa, tsaftacewa, da duk abin da mai shi ya saita. Za ka same su a Jerin dubawa: na yau suna a sama, a shirye don yin alama.",
  "training.lessons.staff-checklists.step2": "Ka yi alama ga abu lokacin da ka yi shi da gaske. Kowace alama tana rubuta wanda ya yi da lokacin da ya yi, don haka mutum na gaba — da mai shi a gida — za su ga abin da aka yi da abin da ya rage.",
  "training.lessons.staff-checklists.step3": "Wasu abubuwa suna buƙatar shaida kafin a yi musu alama: hoton aikin da aka gama, skan na lamba, ko zafin jiki da aka rubuta. Da farko ka ƙara shaida, sannan ka yi alama — abin ba zai yi alama ba tare da ita ba.",
  "training.lessons.staff-checklists.step4": "Ka yi alama ga wani abu bisa kuskure? Cire alamar — amma naka kaɗai. Manaja ko mai shi zai iya cire na kowa, domin alama rubutu ne mai suna.",
  "training.lessons.staff-checklists.step5": "Ba ka taɓa buƙatar izini don yin aiki a jerin dubawa. Ƙirƙirar samfura da zaɓar wa za a ba su aikin mai shi ne, ko na mutumin da mai shi ya ba alamar samfuran jerin dubawa.",
