  "foodSafety.certs.gatedNote": "Takardun shaida suna tafiya tare da fayil ɗin takardun ma’aikata: mai gida kaɗai, ko manaja da mai gida ya amince masa da takardun ma’aikata, zai iya ƙara su ko canza su. Takardun shaidarku na kanku an jera su a nan.",
