  "foodSafety.sds.saveFailed": "Ba a iya ƙara waccan takardar ba.",
  "foodSafety.sds.gatedNote": "Kowane memba na ƙungiya zai iya karanta waɗannan takardu. Mai gida kaɗai, ko manaja da aka amince masa da takardun ma’aikata, zai iya ƙara ɗaya.",
  "foodSafety.sds.loadFailed": "Ba a iya ɗora waɗannan takardu ba.",
