  "foodSafety.sds.removeBody": "Wannan yana cire takardar daga shiryayyen. Sauran takardu suna nan.",
  "foodSafety.mock.title": "Dubawar gwaji",
  "foodSafety.mock.subtitle": "Yi tafiya a kicin kamar yadda mai dubawa zai yi, kafin mai dubawa ya yi.",
  "foodSafety.mock.intro": "Fara dubawar gwaji kuma ka yi wa kowane batu alama a shafin Jerin abubuwan dubawa yayin da kake dubawa. Kowane alama yana yin rijistar wanda ya duba da yaushe — gyara abin da ka samu a kan hanya, fayil ɗin zai nuna aikin.",
  "foodSafety.mock.startButton": "Fara dubawar gwaji na yau",
  "foodSafety.mock.startFailed": "Ba a iya fara dubawar gwaji ba.",
  "foodSafety.mock.startedNote": "Dubawar gwajinku tana cikin jerin abubuwan dubawa na yau.",
  "foodSafety.mock.openChecklists": "Buɗe jerin abubuwan dubawa",
  "foodSafety.mock.item1": "Firiji, injin daskarewa da riƙe zafi suna cikin kewayon tsaronsu, kuma rajistan yanayin zafi cike yake.",
  "foodSafety.mock.item2": "An yi rijistar duba sanyaya da sake dumama, tare da matakin gyara inda karatu ya kuskure.",
  "foodSafety.mock.item3": "Maganin kashe kwayoyin cuta an haɗa shi da ƙarfin da ya dace kuma an yi rijistar dubansa.",
  "foodSafety.mock.item4": "Kowane takardar shaidar abinci tana da inganci, kuma sabuntawa na gudana ga waɗanda za su ƙare nan ba da daɗewa ba.",
  "foodSafety.mock.item5": "Takardun bayanan tsaro suna kan shiryayyen inda dukan ƙungiyar za su iya karanta su.",
  "foodSafety.mock.item6": "Abincin da ke da kwanan wata an yi masa lakabi kuma ana amfani da shi bisa tsarin ƙarewa: wanda ya ƙare da farko da farko.",
  "foodSafety.mock.item7": "Abubuwan da ke haifar da rashin lafiyar an yi musu alama a kowane abinci a cikin matrix na rashin lafiyar.",
  "foodSafety.mock.item8": "Rajistan sharar gida na yau da kullum ne, tare da dalili ga duk abin da aka jefa.",
  "training.lessons.staff-food-safety.title": "Riƙe fayil ɗin lafiyar abinci",
  "training.lessons.staff-food-safety.step1": "Fayil ɗin lafiyar abinci yana zama a kan shiryayyen lafiyar abinci na Kusurwar Gidan abinci: rajistan yanayin zafi, rajistan sanyaya, sake dumama da maganin kashe kwayoyin cuta, takardun shaida, takardun bayanan tsaro da fakitin dubawa.",
  "training.lessons.staff-food-safety.step2": "Karatu da ya fita daga kewayo bai cika ba har sai rubutunsa ya ce abin da ka yi — ka sake sanyaya shi, ka sake dumama shi, ka sake yin maganin kashe kwayoyin cuta, ka jefa shi. Babu rubutu, babu ajiyewa: shigarwar ba ta tsaya.",
  "training.lessons.staff-food-safety.step3": "Yi rijistar duba sanyaya, sake dumama da maganin kashe kwayoyin cuta kamar yanayin zafi: abin da ka duba, karatun, da matakin gyara idan ya kuskure.",
  "training.lessons.staff-food-safety.step4": "Takardun shaida suna gargaɗi kafin su ƙare. Idan naka ya gargaɗe, gaya wa mai gida — kuma kowa zai iya karanta takardun bayanan tsaro a kan shiryayyensu a kowane lokaci.",
  "training.lessons.staff-food-safety.step5": "Kafin dubawa — ko a kowane lokaci — gudanar da dubawar gwaji daga shiryayyen lafiyar abinci kuma ka buga fakitin da ya shirya don dubawa don kwanan watan mai dubawa.",
