  "training.lessons.staff-kitchen-menu.step1": "Buɗe nunin dafa abinci daga kan shelf na Dafa Abinci da Girke-girke kuma zaɓi girke-girken da kuke dafawa.",
  "training.lessons.staff-kitchen-menu.step2": "Matsa rukunoni nawa kuke yi. Kowane adadi a kan allon zai canza bisa ga hakan — dafa daga allo, ba daga ƙwaƙwalwa ba.",
  "training.lessons.staff-kitchen-menu.step3": "Nunin yana nuna hoton girke-girken, sinadaransa bisa ga adadin rukunoninku, da matakansa a jere.",
  "training.lessons.staff-kitchen-menu.step4": "Menu na baƙi yana nuna abincin da mai shi ya sanya alama a kansu kawai. Farashi da alamun alerji suna zuwa daga bayanai, ba daga sake rubutawa ba.",
