  "training.lessons.staff-equipment.title": "Rubutun kayan aiki da ba da rahoton lalacewa",
  "training.lessons.staff-equipment.step1": "Kowace inji a kasuwancinka tana da shafinta a Kayan aiki: yaushe aka saye ta, yaushe garantinta ya ƙare, wa ke yi mata aiki, da duk abin da ya faru da ita.",
  "training.lessons.staff-equipment.step2": "Idan wani abu ya lalace, ba da rahoto a kan injin kanta. Faɗi abin da ya lalace, kuma idan za ka iya ƙara hoton matsalar — rahoton yana shiga tarihin injin da sunanka da lokaci.",
  "training.lessons.staff-equipment.step3": "Za ka iya ba da rahoton lalacewa ne kaɗai idan mai shi ya ba ka alamar rahoton lalacewa. Idan maɓallin ba ya nan, gaya wa mai shi ko manaja, za su buɗe maka ƙofa.",
  "training.lessons.staff-equipment.step4": "Ayyukan gyara — tsaftacewa, cire ƙarfe, sabis — suna da ranakun kamata. Shafin Kayan aiki yana nuna abin da ya kamata da abin da ya wuce, domin kada wani abu ya shuɗe a shiru.",
  "training.lessons.staff-equipment.step5": "Gyare-gyare da kuɗinsu mai shi ko manaja ke rubutawa. Idan an rubuta gyara a kan rahotonka, lalacewar tana bayyana a tarihin injin a matsayin an gyara.",
