  "training.lessons.owner-tip-pooling.title": "Tukunyar alheri da bayanan alheri",
  "training.lessons.owner-tip-pooling.step1": "Buɗe Gidan abinci, sai Ƙungiya da Wuri, sai Raba tukunyar alheri. Mai gida kaɗai yake ganin saitin tukunyar, kaso da bayanai.",
  "training.lessons.owner-tip-pooling.step2": "Zaɓi yadda za a raba tukunyar: ta sa'o'i, ta kashi na matsayi, ko ta maki. Manhajar tana raba daga jadawali da sa'o'in agogo da ke cikinta.",
  "training.lessons.owner-tip-pooling.step3": "Zaɓi lokacin, shigar da adadin tukunyar, duba rabon, sai ka ajiye. Ajiyayyen kaso yana ciyar da hasashen albashi na wancan lokaci.",
  "training.lessons.owner-tip-pooling.step4": "Wallafa ajiyayyen rabo idan ka shirya — ɗan ƙungiya sai ya ga kasonsa kaɗai, kuma ba komai kafin wallafawa.",
  "training.lessons.owner-tip-pooling.step5": "Riƙe bayanan alheri yayin tafiya: ga kowane mutum, ga kowane lokaci, alherin da aka bayar da rahoto — kuma bayanan shekara suna mai da lissafin 8% jimilloli masu shirye ga fom. Manhajar bayanai kawai take riƙewa; ba ta shigar da komai.",
