  "training.lessons.owner-labor-warnings.title": "Saita gargaɗin aiki",
  "training.lessons.owner-labor-warnings.step1": "Buɗe jadawalin ka nemo lambobin kallo. Kowane lamba a can naka ne ka saita don wurinka.",
  "training.lessons.owner-labor-warnings.step2": "Saita sa'o'in mako inda ƙarin lokaci ke farawa a gare ka, da nisan da wani zai iya kusantowa kafin manhajar ta gargaɗe ka.",
  "training.lessons.owner-labor-warnings.step3": "Saita lokacin da ake tsammanin hutu a aiki da tsawon da ya kamata ya yi, da farkon farawa da ƙarshen ƙarshe da kake so a cikin ayyuka.",
  "training.lessons.owner-labor-warnings.step4": "Gina makon kamar yadda aka saba. Gargaɗi suna bayyana a jadawali yayin da sa'o'i ke kusantar layukanka — kafin su wuce su.",
  "training.lessons.owner-labor-warnings.step5": "Yayin da ƙungiyarka ke shiga da fita, wannan kallon yana wucewa a kan sa'o'in da aka riga aka yi, har da hutun da ba a ɗauka ba.",
  "training.lessons.owner-labor-target.title": "Gina makon a gaban manufar aiki",
  "training.lessons.owner-labor-target.step1": "Buɗe Manufar aiki a kan shiryayyen Ƙungiya da Wuri a Kusurwar Gidan Abinci.",
  "training.lessons.owner-labor-target.step2": "Rubuta manufar aikinka a matsayin kashi, da sayarwar da kake tsammani ta makon.",
  "training.lessons.owner-labor-target.step3": "Gina makon a jadawali. Kiyasin kuɗin aiki da % suna sabuntawa daga ayyuka da ƙimar da suke cikin manhajar.",
  "training.lessons.owner-labor-target.step4": "Idan kiyasin % na aiki ya wuce manufarka, shafin yana faɗa a fili, tare da sa'o'i da kuɗin da ke bayansa.",
  "training.lessons.owner-labor-target.step5": "Buga makon daga shafin idan kana so a takarda — takardar da aka buga ita ce takardar da kake gani a allo.",
