  "training.lessons.owner-catering-events.step3": "Zaɓi menu daga abincinka kuma saita rabon kowannensu.",
  "training.lessons.owner-catering-events.step4": "Lura da ajiyar da aka karɓa; app ɗin yana riƙe sauran da ake bi daga jimlar buki. Kai kaɗai ke ganin kuɗin.",
  "training.lessons.owner-catering-events.step5": "Buga takardar buki don kicin da floor — kwafin ma'aikata ba ya nuna kuɗi — kuma duba Shiri, inda abincin buki ya riga ya bayyana.",
  "nav.reservations": "Yin ajiya",
  "plansLib.businessIncludes.reservations": "Yin ajiya da jerin jira — littafin ajiya, jerin jira na daren nan, da tunatarwar da baƙo ya nema",
  "restaurant.doorReservations": "Littafin ajiya da jerin jira na daren nan",
  "staffLib.area.reservationsAccess": "Yin ajiya da jerin jira",
  "staffLib.perm.reservationsHost": "Karɓar ajiya da gudanar da jerin jira (mai karɓa)",
  "staff.memberDialog.reservationsAccessHint": "Da wannan alamar, wannan mutum zai iya karɓar ajiya kuma ya gudanar da jerin jira na daren nan — aikin mai karɓa. Ba tare da ita ba, littafin karatu ne kawai a gare shi. Mai shi da manajoji koyaushe za su iya riƙe littafin.",
  "reservations.title": "Yin ajiya da jerin jira",
  "reservations.subtitle": "Littafin daren nan da dararen da ke zuwa — wa ke zuwa, su nawa ne, da abin da suke buƙata.",
  "reservations.bookNote": "Wannan littafi ne, ba taswirar falon cin abinci ta kai tsaye ba: ba ya bin tebur minti zuwa minti, kuma babu yin ajiya ta intanet a nan — kowane shigarwa ƙungiyar ku ta karɓa ta waya ko a ƙofa.",
  "reservations.hostNote": "Karɓar ajiya aikin mai karɓa ne: mai shi, manaja, ko mutumin da mai shi ya ba alamar mai karɓa. Lambobin waya da imel na baƙi suna rayuwa a cikin wannan littafi kaɗai.",
