  "reservations.deleteBooking": "Goge ajiya",
  "reservations.emptyTitle": "Babu ajiya ga wannan rana",
  "reservations.emptyBody": "Idan baƙo ya yi ajiya ta waya ko a ƙofa, rubuta shi a cikin littafin — jerin yau yana bayyana a shafin Yau kuma ana iya aika shi ga dukan ƙungiyar.",
  "reservations.reminderAsk": "Baƙo yana son tunatarwa",
  "reservations.reminderHint": "Tambayi baƙo da farko. Baƙin da suka ce i kaɗai ke samun tunatarwa — ta imel, kuma ta saƙo idan an saita saƙonnin rubutu.",
  "reservations.remindersOn": "Tunatarwa na kunne",
