  "reservations.reminderSent": "An aika tunatarwa",
  "reservations.depositLabel": "An karɓi ajiyar kuɗi",
  "reservations.depositHowLabel": "Ajiyar kuɗi — yaya",
  "reservations.depositNote": "Rikodin ajiyar kuɗin da aka riga aka karɓa, da yadda aka karɓa. Manhajar ba ta riƙe kuɗi a kati kuma ba ta karɓar biyan kuɗi a nan.",
  "reservations.digestButton": "Aika jerin yau ga ƙungiyar",
