  "waitlist.title": "Jerin jira na daren nan",
  "waitlist.subtitle": "Layin daren nan mai rai — jeri, ba taswirar falon kai tsaye ba. Kai ne ke faɗin lokacin da ƙungiya za ta zauna.",
  "waitlist.addButton": "Ƙara zuwa jerin jira",
