  "waitlist.readyNotAvailable": "Ba a iya sanar da su ba: saƙo ba ya samuwa tukuna kuma ba a ba da imel ba.",
  "waitlist.emptyTitle": "Babu mai jira",
  "waitlist.emptyBody": "Baƙin da ba su da ajiya da ke jiran tebur suna zuwa nan, tare da jiran da ka faɗa musu.",
  "waitlist.saved": "An ƙara zuwa jerin jira.",
  "waitlist.saveFailed": "Ba a iya ajiye shigarwar jerin jira ba. Duba cikakkun bayanai kuma sake gwadawa.",
  "apiErrors.reservationsHost": "Mai shi, manaja, ko mutumin da mai shi ya ba alamar mai karɓa kaɗai zai iya karɓar ajiya.",
  "apiErrors.reservationsInvalid": "Duba cikakkun bayanan ajiya kuma sake gwadawa.",
  "apiErrors.waitlistInvalid": "Duba cikakkun bayanan jerin jira kuma sake gwadawa.",
  "training.lessons.owner-reservations.title": "Karɓar ajiya da gudanar da jerin jira",
  "training.lessons.owner-reservations.step1": "Buɗe Yin ajiya a kan shelf ɗin Falo da Baƙi na Kusurwar Gidan Abinci. Littafin yana riƙe kowane ajiya; jerin jira da ke ƙarƙashinsa yana riƙe baƙin daren nan ba tare da ajiya ba.",
  "training.lessons.owner-reservations.step2": "Ƙara ajiya da kwanan wata da lokaci, sunan ƙungiya da girma, lambar waya, da tebur ko sashe a cikin kalmominka. Rubuta abin da kicin ya kamata ya sani — rashin lafiyar abinci, kujera mai tsayi, ranar tunawa.",
  "training.lessons.owner-reservations.step3": "Tambayi baƙo ko yana son tunatarwa, kuma sanya alama a akwatin idan ya ce i kaɗai. Tunatarwa suna tafiya ta imel, kuma ta saƙo idan an saita saƙo. Rubuta kowace ajiyar kuɗin da aka riga aka karɓa — nawa da yaya — a matsayin rikodi kawai.",
  "training.lessons.owner-reservations.step4": "Yi aiki a littafin duk daren: yi wa kowace ƙungiya alama a matsayin ta zauna, ba ta zo ba, ko an soke. Aika jerin yau ga ƙungiyar daga littafin domin kowa ya yi aiki daga shafi ɗaya.",
  "training.lessons.owner-reservations.step5": "Ga baƙin da ba su da ajiya, ƙara ƙungiyar zuwa jerin jira tare da jiran da ka faɗa. Idan teburinsu ya shirya, danna Tebur ya shirya — ba da lamba don wannan saƙo shi ne i na baƙo.",
  "apiErrors.smsInvalid": "Saƙon rubutu yana buƙatar lamba da saƙo.",
  "apiErrors.smsFailed": "Sabis ɗin saƙon rubutu bai karɓi saƙon ba.",
  "nav.standingOrders": "Umarnin dindindin",
  "restaurant.doorStandingOrders": "Umarnin dindindin da kwatancen farashi — abubuwan yau da kullun da ake maimaitawa a matsayin daftari da kuke tabbatarwa, da farashin kowane mai kaya don wani sinadari, gefe da gefe",
  "plansLib.businessIncludes.standingOrders": "Umarnin dindindin da kwatancen farashin masu kaya",
  "standingOrders.title": "Umarnin dindindin",
  "standingOrders.subtitle": "Abubuwan yau da kullun da ake maimaitawa, an saita sau ɗaya — umarnin Talata da kowane umarni na yau da kullun bayan sa.",
  "standingOrders.draftNote": "Umarni na dindindin koyaushe yana zuwa a matsayin daftarin odar sayayya a cikin Sayayya don tabbatarwarku. App ɗin ba ya taɓa aika oda da kansa.",
  "standingOrders.newButton": "Sabon umarni na dindindin",
  "standingOrders.nameLabel": "Suna",
