  "standingOrders.addLine": "Ƙara layi",
  "standingOrders.saveButton": "Ajiye umarni na dindindin",
  "standingOrders.saved": "An ajiye umarnin dindindin.",
  "standingOrders.saveFailed": "Ba a iya ajiye umarnin dindindin ba. Duba cikakkun bayanai ku sake gwadawa.",
  "standingOrders.emptyTitle": "Babu umarnin dindindin tukuna",
  "standingOrders.emptyBody": "Saita abubuwan da kuke oda akai-akai — kayan lambu kowane Talata, busassun kaya kowane Juma'a — sau ɗaya, kuma ku ƙirƙiri daftarin kowane mako da taɓawa ɗaya.",
  "standingOrders.makeDraftButton": "Ƙirƙiri daftarin wannan mako",
  "standingOrders.draftMade": "Daftarin oda {number} yana jira a cikin Sayayya don tabbatarwarku.",
  "standingOrders.draftFailed": "Ba a iya ƙirƙirar daftarin oda ba. Sake gwadawa.",
  "standingOrders.activeLabel": "Mai aiki",
  "standingOrders.lineSummary": "{lines} layuka · {total}",
  "priceBook.title": "Littafin farashin masu kaya",
  "priceBook.subtitle": "Sinadari ɗaya, farashin kowane mai kaya, gefe da gefe — sabon farashin da kowane mai kaya ya caji, daga daftarin ku da odarku. Mafi arha yana zuwa farko.",
  "priceBook.cheapest": "Mafi arha",
  "priceBook.colSupplier": "Mai kaya",
  "priceBook.colPrice": "Farashi",
  "priceBook.colDate": "Kwanan wata",
  "priceBook.colSource": "Tushe",
  "priceBook.sourceInvoice": "Daftari",
  "priceBook.sourceOrder": "Oda",
  "priceBook.emptyTitle": "Babu farashi tukuna",
  "priceBook.emptyBody": "Farashi yana bayyana a nan yayin da daftarin masu kaya da oda ke shigowa — kowane farashin da app ɗin ya tattara yana shiga littafin da kansa.",
  "priceBook.printButton": "Buga littafin farashi",
  "priceBook.docTitle": "Littafin farashin masu kaya",
  "apiErrors.standingOrdersForbidden": "Mai shi kawai, manaja, ko mutumin da ke da izinin sayayya ne zai iya saita umarnin dindindin.",
  "apiErrors.standingOrdersInvalid": "Duba cikakkun bayanan umarnin dindindin ku sake gwadawa.",
  "training.lessons.owner-standing-orders.title": "Umarnin dindindin da kwatanta farashin masu kaya",
  "training.lessons.owner-standing-orders.step1": "Buɗe Umarnin dindindin a kan shelf ɗin Ajiya da Oda na Kusurwar Gidan Abinci. Odarku masu maimaituwa suna zaune a nan, kuma a ƙarƙashinsu littafin farashin masu kaya.",
  "training.lessons.owner-standing-orders.step2": "Saita umarni na dindindin sau ɗaya: ba shi suna, zaɓi mai kayansa da ranar da yake dominta, kuma ƙara layukan abubuwan yau da kullun da adadin da kuka saba oda.",
  "training.lessons.owner-standing-orders.step3": "Lokacin da ranar ta zo, taɓa Ƙirƙiri daftarin wannan mako. App ɗin yana rubuta daftarin odar sayayya ɗaya a cikin Sayayya, an yi masa farashi da sabon farashin wancan mai kaya daga littafin — duba shi, canza abin da ake buƙata, kuma ku aika da kanku. App ɗin ba ya taɓa aika oda da kansa.",
  "training.lessons.owner-standing-orders.step4": "Karanta littafin farashi kafin ku yi oda: sinadari ɗaya, sabon farashin kowane mai kaya gefe da gefe, mafi arha farko, tare da kwanan wata da ko farashin daga daftari ne ko daga oda.",
  "training.lessons.owner-standing-orders.step5": "Ku kiyaye littafin da gaskiya ta hanyar shigar da daftarin masu kaya yayin da suke zuwa — kowane sabon farashi yana shiga littafin kuma daftari na gaba ana yi masa farashi daga gare shi.",
  "nav.productionOrder": "Oda bisa ga samarwa",
  "restaurant.doorProductionOrder": "Oda bisa ga samarwa — juya gudanar batch ko taron catering zuwa odar sinadaran da yake buƙata",
  "plansLib.businessIncludes.productionOrder": "Oda bisa ga samarwa da takardun shiri da ke cika kansu",
  "productionOrder.title": "Oda bisa ga samarwa",
  "productionOrder.subtitle": "Zaɓi shirin samarwa — gudanar batch ko taron catering. Manhajar tana lissafa sinadaran da ake buƙata, ta rage abin da ke hannu, ta sa sauran a siffar jagorar oda.",
  "productionOrder.draftNote": "Kowace oda da wannan shafi ya ƙirƙira tana zuwa a matsayin daftarin odar saye a cikin Sayayya don tabbatarwarka. Manhajar ba ta taɓa aika oda da kanta.",
  "productionOrder.sourceLabel": "Shirin samarwa",
  "productionOrder.sourceBatch": "Gudanar batch",
  "productionOrder.sourceEvent": "Taron catering",
  "productionOrder.recipeLabel": "Girke-girke",
