  "productionOrder.draftFailed": "Ba a iya ƙirƙirar daftarin oda ba. Sake gwadawa.",
  "productionOrder.emptyTitle": "Babu shirye-shiryen samarwa tukuna",
  "productionOrder.emptyBody": "Gudanar da batch daga shafin Shiri ko yin ajiyar taron catering, sai a iya lissafa odar sinadaransa a nan.",
  "productionOrder.printButton": "Buga shirin oda",
  "productionOrder.docTitle": "Oda bisa ga samarwa",
  "productionOrder.batchSummary": "{name} — mek {makes}",
  "productionOrder.eventSummary": "{name} — {date}",
  "apiErrors.productionOrderForbidden": "Mai gida kawai, manaja, ko mutum mai izinin sayayya ne zai iya oda bisa ga samarwa.",
  "apiErrors.productionOrderInvalid": "Duba shirin samarwa ka sake gwadawa.",
  "prepSuggest.title": "Shawarwarin shiri",
  "prepSuggest.subtitle": "Adadin da aka ba da shawara daga matakan par ɗinka, ajiyayyu, da abin da aka riga aka shirya. Manhajar tana nuna lissafinta — babu abin da ke canzawa a takardar har sai ka gudanar da batch ɗin.",
  "prepSuggest.bookedLine": "An ajiye: baƙi {guests} a ajiyayyu · taruka {events} masu zuwa",
  "prepSuggest.suggested": "An ba da shawarar mek {makes}",
  "prepSuggest.whyLine": "Par {par} · tarukan da aka ajiye {events} · an riga an shirya {prepped}",
  "prepSuggest.none": "Babu ƙarin abin shiryawa — matakan par sun rufe kuma babu taron da aka ajiye da ke jawo.",
  "training.lessons.owner-production-order.title": "Oda bisa ga samarwa da takardun shiri da ke cika kansu",
  "training.lessons.owner-production-order.step1": "Buɗe Oda bisa ga samarwa a kan shiryayyar Kaya da Oda ta Kusurwar Gidan Abinci. Shirin samarwa — gudanar batch ko taron catering — ya zama odar sinadarai a nan.",
  "training.lessons.owner-production-order.step2": "Zaɓi shirin: girke-girke da mek nawa don gudanar batch, ko ɗaya daga cikin tarukan catering ɗinka da aka ajiye. Taɓa Lissafa odar.",
  "training.lessons.owner-production-order.step3": "Manhajar tana buɗe girke-girken, ta rage abin da ke hannu, ta zagaye sauran sama zuwa girman fakiti, a rukuni bisa ga mai kaya — siffar jagorar oda.",
  "training.lessons.owner-production-order.step4": "Taɓa Ƙirƙiri daftarin oda sai daftarin odar saye ɗaya ga kowane mai kaya ya zo Sayayya. Ka duba ka aika da kanka — manhajar ba ta taɓa aika oda da kanta.",
  "training.lessons.owner-production-order.step5": "A shafin Shiri, takardar tana cika kanta: mek ɗin da aka ba da shawara suna fitowa daga matakan par ɗinka, ajiyayyun da ke cikin ajiyayyu da taruka, da abin da aka riga aka shirya — ana nuna shawarar, kuma babu abin da ke canzawa har sai ka gudanar da batch ɗin.",
  "nav.barCounting": "Ƙidaya mashaya",
  "restaurant.doorBarCounting": "Ƙidaya mashaya — ƙidaya buɗaɗɗun kwalabe a cikin kashi goma da kegs haka nan, ta wurin ajiya",
  "plansLib.businessIncludes.barCounting": "Ƙidaya mashaya don rabin kwalabe da kegs",
  "barCounting.title": "Ƙidaya mashaya",
  "barCounting.subtitle": "Ƙidaya abin da yake a buɗe, ta wurin ajiya. Zamar da slider zuwa yadda buɗaɗɗen kwalbar take ganin cike — a cikin kashi goma — kuma ka rubuta kegs haka nan. Cikakkun kwalabe da kegs suna ƙidaya cikakke.",
  "barCounting.offTitle": "Ƙidaya mashaya a kashe take",
  "barCounting.offBody": "Ƙidaya mashaya tana ɓoye har sai mai shi ya kunna ta. Ka kunna ta kawai idan wannan kasuwancin yana da mashaya — tana bayyana a kan shelf na Stock & Ordering.",
  "barCounting.turnOnButton": "Kunna ƙidaya mashaya",
  "barCounting.turnOffButton": "Kashe ƙidaya mashaya",
  "barCounting.enabledNote": "Ƙidaya mashaya a kunne take don wannan kasuwancin. Ka kashe ta ƙofar shelf za ta sake ɓoyewa; ƙidaya da aka riga aka ajiye suna zama a cikin Ƙidaya.",
  "barCounting.ownerOnlyNote": "Mai shi kaɗai zai iya kunna ƙidaya mashaya.",
  "barCounting.areaLabel": "Wurin ajiya",
  "barCounting.kindBottle": "Kwalba",
  "barCounting.kindKeg": "Keg",
  "barCounting.fullLabel": "Cikakku",
  "barCounting.partialLabel": "Buɗaɗɗen — yaya ta cika",
  "barCounting.countedLabel": "An ƙidaya",
  "barCounting.expectedLabel": "A kan rikodin",
  "barCounting.colProduct": "Kwalba / keg",
  "barCounting.saveButton": "Ajiye ƙidaya mashaya",
  "barCounting.savedNote": "Ƙidaya mashaya {number} an ajiye ta a cikin Ƙidaya — ka duba ta ka yi amfani da ita a can, kamar kowace ƙidaya.",
  "barCounting.saveFailed": "Ba a iya ajiye ƙidaya mashaya ba. Sake gwadawa.",
  "barCounting.emptyTitle": "Babu abin da aka ajiye a wannan wurin tukuna",
  "barCounting.emptyBody": "Ƙidaya mashaya tana ƙidaya abin da wurin ajiya ya riƙe. Ka fara ƙara stock zuwa wannan wurin, sannan ka ƙidaya kwalabe da kegs a nan.",
  "barCounting.printButton": "Buga takardar ƙidaya",
  "barCounting.docTitle": "Ƙidaya mashaya",
  "barCounting.docArea": "{name}",
  "barCounting.varianceNote": "Ƙidaya mashaya da aka ajiye zaman ƙidaya ne: bambance-bambancenta daga rikodin su ne ainihin gefen bambancin theoretical-vs-actual.",
  "apiErrors.barCountingForbidden": "Mai shi kaɗai zai iya kunna ko kashe ƙidaya mashaya.",
  "apiErrors.barCountingCountForbidden": "Mai shi, manaja, ko mutumin da ke da izinin ƙidaya kaɗai zai iya ajiye ƙidaya mashaya.",
  "apiErrors.barCountingInvalid": "Duba ƙidaya mashaya kuma sake gwadawa.",
  "apiErrors.barCountingOff": "Ba a kunna ƙidaya mashaya don wannan kasuwancin ba.",
  "training.lessons.owner-bar-counting.title": "Ƙidaya mashaya: rabin kwalabe da kegs",
  "training.lessons.owner-bar-counting.step1": "Kunna ƙidaya mashaya daga shelf na Stock & Ordering — tana ɓoye har sai ka yi haka, don haka kasuwancin da ba shi da mashaya ba ya taɓa ganin ta. Maɓallin na mai shi kaɗai ne.",
  "training.lessons.owner-bar-counting.step2": "Buɗe Ƙidaya mashaya ka zaɓi wurin ajiya da kake tsaye a ciki. Takardar ta jera abin da wurin ya riƙe, tare da abin da ke kan rikodin kusa da kowace kwalba da keg.",
  "training.lessons.owner-bar-counting.step3": "A kowace layi, ka faɗi ko kwalabe ne ko keg, ka shigar da cikakkun, sannan ka zamar da slider zuwa yadda buɗaɗɗen take ganin cike — a cikin kashi goma, ana hukunta shi da hotonta. Lambar da aka ƙidaya ita ce cikakkun ƙara kashi goma na buɗaɗɗen.",
  "training.lessons.owner-bar-counting.step4": "Ajiye ƙidaya mashaya. Tana sauka a cikin Ƙidaya a matsayin zaman ƙidaya na yau da kullun — ka aika ta don dubawa ka yi amfani da ita a can, kuma shelf ɗin ya saita zuwa abin da ka ƙidaya.",
  "training.lessons.owner-bar-counting.step5": "Bambance-bambancen da ƙidaya mashaya take samu suna ciyar da bambancin theoretical-vs-actual, don haka kwalbar da take ci gaba da zuwa gajarta tana nuna kanta a can. Buga takardar ƙidaya daga wannan shafin lokacin da kake son ƙidaya a kan takarda.",
  "nav.locationsRollup": "Duk wurare",
