  "locationsRollup.weekNote": "Ɓarna ita ce duk abin da aka rubuta tun Litinin. Farashin abinci % shi ne ainihin farashin abincinka masu farashi idan aka kwatanta da farashinsu.",
  "locationsRollup.printButton": "Buga taƙaitaccen",
