  "locationsRollup.emptyTitle": "Wuri ɗaya kaɗai zuwa yanzu",
  "locationsRollup.emptyBody": "Wannan shafi yana bayyana idan kana da kasuwanci biyu ko fiye. Da wuri ɗaya, duk wannan yana rayuwa a shafukan wannan kasuwancin.",
  "locationsRollup.loadFailed": "Ba a iya loda taƙaitaccen ba. Sake gwadawa.",
  "locationsRollup.pushTitle": "Kwafi zuwa sauran wurarena",
  "locationsRollup.pushBody": "Daina sake rubuta canji ɗaya a kowane kasuwanci. Kwafi girke-girke, ko farashi da farashin wannan wurin, zuwa wuraren da ka zaɓa. Kayayyaki da abinci ana daidaita su da SKU da farko, sannan da suna; duk abin da ba shi da daidaito ana kiran sunansa, ba a taɓa watsar da shi a shiru ba.",
