  "locationsRollup.dishUnmatched": "A {business} abincin kansa ba shi da daidaito, don haka kwafin yana jira a matsayin daftari.",
  "apiErrors.locationsRollupForbidden": "Mai shi kaɗai zai iya amfani da taƙaitaccen duk wurare.",
  "apiErrors.locationsRollupInvalid": "Duba buƙatar kwafi ka sake gwadawa.",
  "training.lessons.owner-locations-rollup.title": "Duk wurare a shafi ɗaya",
  "training.lessons.owner-locations-rollup.step1": "Buɗe shelf ɗin Wurare ka zaɓi Duk wurare. Shelf ɗin kansa yana bayyana ne kawai idan kana da kasuwanci biyu ko fiye, don haka mai wuri ɗaya ba ya taɓa ganinsa.",
  "training.lessons.owner-locations-rollup.step2": "Karanta layin kowane wuri: farashin abinci %, darajar kaya, ɓarnar wannan mako da abin da ya yi ƙasa. Wurin da ya fito fili shi ne raunin da za a fara aiki a kai.",
  "training.lessons.owner-locations-rollup.step3": "Buga taƙaitaccen idan kana son kwatancen a takarda — yana bugawa kamar yadda yake a allon.",
  "training.lessons.owner-locations-rollup.step4": "Don kwafi girke-girke, zaɓe shi, ka yi wa wuraren da ya kamata ya isa alama, ka kwafi. Sinadaran ana daidaita su da SKU da farko, sannan da suna; duk abin da ba shi da daidaito ana kiran sunansa a sakamakon, ba a taɓa watsar da shi a shiru ba.",
  "training.lessons.owner-locations-rollup.step5": "Don kwafi farashi, yi amfani da Kwafi farashi da farashin kaya da alamu na wuri iri ɗaya. Girke-girken da abincinsa ba shi da daidaito a wuri yana sauka a can a matsayin daftari, a shirye don ka haɗa shi.",
  "plansLib.businessIncludes.recipeCostLink": "Kuɗin girke-girke da ke bin sabuwar farashin daftari",
  "recipes.costUpdatedTitle": "An sabunta kuɗi",
  "recipes.costUpdatedNote": "{ingredient} yanzu yana tsaye a kan farashin {price} na daftarin {invoice} na {supplier} (an sabunta a {date}).",
  "recipes.costUpdatedNotePlain": "{ingredient} yanzu yana tsaye a kan sabuwar farashin daftari {price} na {supplier} (an sabunta a {date}).",
  "ops.invoices.acceptNote": "Karɓar daftari yana sa farashinsa su zama kuɗin yanzu na kayan haɗinsa, kuma kowane girki da ke amfani da su yana sake ƙididdige kuɗinsa — girkin yana nuna rubutu mai suna farashin daftarin da yake tsaye a kansa.",
  "training.lessons.owner-recipe-cost-link.title": "Kuɗin girke-girke na bin farashin daftari",
  "training.lessons.owner-recipe-cost-link.step1": "Shigar da daftarin mai kaya a matsayin daftarin gwaji yayin da kake duba shi da kayan da aka kawo.",
  "training.lessons.owner-recipe-cost-link.step2": "Idan daftarin ya yi daidai, saita matsayinsa zuwa An Karɓa.",
  "training.lessons.owner-recipe-cost-link.step3": "Karɓarsa yana sa kowane farashin da aka biya ya zama kuɗin yanzu na wannan kayan haɗi.",
  "training.lessons.owner-recipe-cost-link.step4": "Kowane girki da ke amfani da wannan kayan haɗi yana sake ƙididdige kuɗinsa daga sabon farashi nan take.",
  "training.lessons.owner-recipe-cost-link.step5": "Buɗe girki don ganin rubutun sabunta kuɗinsa, mai suna farashin daftarin da yake tsaye a kansa — kuɗi ba ya taɓa canzawa a ɓoye.",
  "plansLib.includes.shiftSwaps": "Musayar sauyin aiki da samuwar ma'aikata — miƙa sauyi zuwa tafki ko musanya, tare da amincewar manaja",
  "nav.shiftSwaps": "Musayar sauyin aiki",
