  "training.lessons.owner-shift-swaps.title": "Musayar sauyin aiki da samuwa",
  "training.lessons.owner-shift-swaps.step1": "Buɗe jadawalin ƙungiya ka nemo shafin Musayar sauyin aiki. Kowane memba na ƙungiya zai iya miƙa sauyi a can.",
  "training.lessons.owner-shift-swaps.step2": "Memba na ƙungiya yana miƙa sauyi zuwa tafki, inda duk abokin aiki mai aiki iri ɗaya zai iya ɗauka, ko ya miƙa musaya ga abokin aiki.",
  "training.lessons.owner-shift-swaps.step3": "Babu abin da ke motsi da kansa: manaja na amincewa da kowace musaya, kuma a lokacin ne kawai jadawalin ke sabunta kansa.",
  "training.lessons.owner-shift-swaps.step4": "Idan musaya za ta tura wani bayan layin ƙarin sa'o'i da ka saita, manhajar za ta yi mata tuta kafin amincewa, domin manaja ya ga tutar da farko.",
  "training.lessons.owner-shift-swaps.step5": "Kowane mutum yana riƙe samuwarsa — lokacin da zai iya aiki — a cikin manhajar, kuma wanda ke gina jadawalin yana ganinta yayin da yake gina makon.",
