  "plansLib.businessIncludes.lotTraceability": "Lambobin lot, mai neman kira da mai ba da kaya — mai ba da kaya da lot a kowace isarwa, janyewa da ke kulle batch, da log na bin diddigi da za a iya bugawa",
  "nav.lotTrace": "Lots da kira",
