  "training.lessons.owner-lot-traceability.title": "Lambobin lot, kira da bin diddigin mai ba da kaya",
  "training.lessons.owner-lot-traceability.step1": "Lokacin da isarwa ta zo, buɗe Lots da kira a kan shiryayyen Stock da Oder kuma ka rubuta ta: samfurin, mai ba da kaya, yawa — da lambar lot da aka buga a kan akwatin, ga kowane abu.",
  "training.lessons.owner-lot-traceability.step2": "A kan allo ɗaya na ƙofar baya, rubuta zafin isarwa don kayan sanyi, da duk abin da ka ƙi da dalili. Ƙi da aka rubuta ita ce shaidar da bashin mai ba da kaya ke buƙata.",
  "training.lessons.owner-lot-traceability.step3": "Don kayan da ake sayarwa da nauyi, rubuta ainihin nauyin da ya zo. App ɗin yana ƙidaya ainihin farashi a kowane fam ko kilo daga ciki, don haka kuɗin girke-girke ya kasance mai gaskiya.",
  "training.lessons.owner-lot-traceability.step4": "Idan an kira lot, janye shi: batch ɗin yana kullewa don kada kowa ya yi amfani da shi, janyewar kanta ta zama rikodi, kuma abin da ya rage yana zuwa log na sharar gida da dalilinsa.",
  "training.lessons.owner-lot-traceability.step5": "Yi amfani da mai neman kira da log na bin diddigi don amsa inda lot yake da duk inda ya je — ta mai ba da kaya ko ta lot — kuma ka buga log ɗin don sashen lafiya ko mai ba da kaya.",
